INSERT INTO `blogs` (`id`, `slug`, `title`, `category`, `date`, `readTime`, `author`, `image`, `excerpt`, `content`, `order`, `isActive`, `createdAt`, `updatedAt`, `heading`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `sections`) VALUES (2, 'maldives-all-inclusive-vs-half-board-expert-guide-from-coimbatore', 'Maldives All-Inclusive vs Half-Board: Expert Guide from Coimbatore', 'Honeymoon', 'Sep 28, 2026', '5 min read', 'Island Curator', '/assets/images/slide/slide1.jpg', 'Planning your honeymoon or private villa escape? Discover the key differences between meal plans, transfer speedboats, and seaplanes in the Maldives.', 'Choosing the right meal plan and island transfer in the Maldives can make all the difference between a stress-free luxury escape and unexpected resort bills. Since every resort sits on its own private coral island, all dining and activities happen within your resort.\n\n1. All-Inclusive vs Half-Board\nHalf-Board includes daily breakfast and dinner, making it ideal for light daytime eaters. However, All-Inclusive covers breakfast, lunch, dinner, unlimited beverages, and often sunset cruises or snorkeling gear—giving couples complete peace of mind.\n\n2. Speedboat vs Seaplane Transfers\nResorts in North and South Malé Atolls are easily reached within 20 to 45 minutes by luxury speedboat, whereas remote atolls offer iconic 35-minute scenic seaplane flights over turquoise lagoons.', 2, 1, '2026-10-13 06:13:00', '2026-10-13 16:02:13', '1. All-Inclusive vs Half-Board & Island Transfers', 'Maldives All-Inclusive vs Half-Board Guide for Honeymooners | Golden Travels', 'Compare Maldives meal plans, seaplane vs speedboat transfers, and private overwater villa inclusions before booking your island getaway.', 'maldives all inclusive vs half board, maldives honeymoon guide, maldives transfer cost, water villa package maldives', 'https://goldentravels.in/blog/maldives-all-inclusive-vs-half-board-expert-guide-from-coimbatore', NULL);
INSERT INTO `blogs` (`id`, `slug`, `title`, `category`, `date`, `readTime`, `author`, `image`, `excerpt`, `content`, `order`, `isActive`, `createdAt`, `updatedAt`, `heading`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `sections`) VALUES (3, 'top-7-romantic-international-honeymoon-destinations-for-2026', 'Top 7 Romantic International Honeymoon Destinations for 2026', 'Honeymoon', 'Sep 20, 2026', '7 min read', 'Luxury Advisor', '/assets/images/tour/3.jpg', 'Looking for privacy, infinity pools, and candlelit dinners by the ocean? Explore our top handpicked honeymoon destinations curated for newly-wed couples.', 'Your honeymoon is the first chapter of a lifetime of adventures together. At Golden Travels, we curate private, unhurried itineraries designed exclusively for couples seeking romance, comfort, and unforgettable backdrops.\n\n1. Tropical Private Pool Villas\nFrom Bali\'s Ubud rainforest infinity pools and Nusa Dua beaches to Maldives overwater bungalows, private villa stays with floating breakfasts and candlelit beachside dining remain top favorites.\n\n2. European Fairytale Escapes\nFor couples who love scenic train rides, cobblestoned towns, and alpine lakes, combining Switzerland\'s Interlaken and Lucerne with Paris creates the ultimate romantic European journey.', 3, 1, '2026-10-13 06:13:00', '2026-10-13 16:02:13', '1. Romantic Island Villas & European Fairytales', 'Top 7 Romantic International Honeymoon Destinations 2026 | Golden Travels', 'Discover the most romantic destinations for couples: private Bali pool villas, Maldives overwater escapes, Swiss Alps lakes, and Mediterranean sunsets.', 'best honeymoon destinations 2026, romantic international holidays, luxury honeymoon trips, couple vacation packages', 'https://goldentravels.in/blog/top-7-romantic-international-honeymoon-destinations-for-2026', NULL);
INSERT INTO `blogs` (`id`, `slug`, `title`, `category`, `date`, `readTime`, `author`, `image`, `excerpt`, `content`, `order`, `isActive`, `createdAt`, `updatedAt`, `heading`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `sections`) VALUES (4, 'how-to-secure-schengen-visa-with-ease-essential-checklist', 'How to Secure Schengen Visa with Ease: Essential Checklist', 'Visa Guide', 'Sep 15, 2026', '8 min read', 'Visa Concierge', '/assets/images/tour/1.jpg', 'A complete step-by-step guide on documents, appointment slots, travel insurance, and itinerary planning for travelers applying from South India.', 'Applying for a Schengen visa to explore 29 European countries doesn\'t have to feel overwhelming. With proper documentation and timely appointment booking, Indian travelers can achieve a smooth approval process.\n\n1. Core Documentation Checklist\nEnsure your passport has at least 6 months validity beyond your return date, along with 6 months of stamped bank statements, 3 years of ITR acknowledgments, employment/business proof, and Schengen-compliant travel insurance covering at least €30,000.\n\n2. Day-Wise Itinerary & Cover Letter\nEmbassies look for a clear, well-structured cover letter paired with confirmed hotel vouchers, internal train/flight bookings, and return air tickets—all of which our Coimbatore visa concierge team prepares end-to-end.', 4, 1, '2026-10-13 06:13:00', '2026-10-13 16:02:13', '1. Core Documentation Checklist & Appointment Slots', 'How to Secure Schengen Visa with Ease: 2026 Document Checklist | Golden Travels', 'Step-by-step checklist for South Indian travelers applying for Schengen visas: cover letter, appointment booking, insurance and hotel vouchers.', 'schengen visa checklist, europe visa from south india, schengen visa appointment tips, visa assistance coimbatore', 'https://goldentravels.in/blog/how-to-secure-schengen-visa-with-ease-essential-checklist', NULL);
INSERT INTO `blogs` (`id`, `slug`, `title`, `category`, `date`, `readTime`, `author`, `image`, `excerpt`, `content`, `order`, `isActive`, `createdAt`, `updatedAt`, `heading`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `sections`) VALUES (5, 'bali-beyond-the-beaches-cultural-luxury-escapes-in-ubud', 'Bali Beyond the Beaches: Cultural & Luxury Escapes in Ubud', 'Asia', 'Sep 10, 2026', '5 min read', 'Asia Planner', '/assets/images/tour/4.jpg', 'Immerse in lush rice terraces, private forest pool villas, and spiritual temple ceremonies across the magical heart of Bali.', 'While Southern Bali is famous for its golden sunset beaches and cliffside clubs in Uluwatu and Seminyak, the true cultural soul of the island beats in the emerald highlands of Ubud.\n\n1. Tegalalang Rice Terraces & Jungle Swings\nWake up early to stroll through misty UNESCO-recognized rice paddies, visit waterfalls tucked inside tropical valleys, and enjoy panoramic jungle swings overlooking the Ayung River gorge.\n\n2. Boutique Sanctuary Stays\nPair 3 nights in a private heated pool villa in Ubud with 3 nights by the beach in Nusa Dua or Seminyak for the best of both worlds.', 5, 1, '2026-10-13 06:13:00', '2026-10-13 16:02:13', '1. Tegalalang Rice Terraces & Boutique Stays in Ubud', 'Bali Beyond the Beaches: Cultural & Luxury Escapes in Ubud | Golden Travels', 'Explore emerald rice terraces, private forest pool villas, holy spring water temples and luxury wellness retreats in Ubud, Bali.', 'ubud bali guide, luxury villas ubud, bali cultural tours, bali honeymoon tips, best places in bali', 'https://goldentravels.in/blog/bali-beyond-the-beaches-cultural-luxury-escapes-in-ubud', NULL);
INSERT INTO `blogs` (`id`, `slug`, `title`, `category`, `date`, `readTime`, `author`, `image`, `excerpt`, `content`, `order`, `isActive`, `createdAt`, `updatedAt`, `heading`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `sections`) VALUES (6, 'vietnam-essentials-halong-bay-cruises-ba-na-hills-phu-quoc-beaches', 'Vietnam Essentials: Halong Bay Cruises, Ba Na Hills & Phu Quoc Beaches', 'Asia', 'Sep 02, 2026', '6 min read', 'International Lead', '/assets/images/packages/vietnam.jpg', 'A complete 9-day traveler guide covering Hanoi heritage, Halong Bay overnight cruises, Golden Bridge in Danang, and tropical Phu Quoc adventures.', '### 1. Halong Bay Cruises & Ba Na Hills Highlights\n\nVietnam has rapidly become one of the most loved international destinations for Indian families and couples thanks to its dramatic karst landscapes, French-colonial heritage, and warm hospitality.\n\n1. North &amp; Central Highlights: Hanoi, Halong Bay &amp; Da Nang\nBegin in Hanoi\'s Old Quarter before boarding a 5-star overnight cruise across the emerald waters of Halong Bay. Next, fly to Da Nang to walk across the iconic Golden Bridge at Ba Na Hills and explore lantern-lit Hoi An.\n\n2. Southern Island Finale: Phu Quoc\nWrap up your holiday in Phu Quoc with the world\'s longest over-sea cable car ride to Hon Thom Island, VinWonders theme park, and Grand World\'s Venice-style canal shows.', 6, 1, '2026-10-13 06:13:00', '2026-10-17 06:23:03', '1. Halong Bay Cruises & Ba Na Hills Highlights', 'Vietnam Travel Guide: Halong Bay, Ba Na Hills & Phu Quoc | Golden Travels', 'Essential travel tips for visiting Vietnam: overnight Halong Bay cruises, walking the Golden Bridge in Da Nang, and tropical relaxation in Phu Quoc.', 'vietnam travel guide, halong bay cruise tips, ba na hills da nang, phu quoc island guide, vietnam tour itinerary', 'http://localhost:3000/blog/vietnam-essentials-halong-bay-cruises-ba-na-hills-phu-quoc-beaches', '[{"heading":"1. Halong Bay Cruises & Ba Na Hills Highlights","content":"Vietnam has rapidly become one of the most loved international destinations for Indian families and couples thanks to its dramatic karst landscapes, French-colonial heritage, and warm hospitality.\\n\\n1. North &amp; Central Highlights: Hanoi, Halong Bay &amp; Da Nang\\nBegin in Hanoi\'s Old Quarter before boarding a 5-star overnight cruise across the emerald waters of Halong Bay. Next, fly to Da Nang to walk across the iconic Golden Bridge at Ba Na Hills and explore lantern-lit Hoi An.\\n\\n2. Southern Island Finale: Phu Quoc\\nWrap up your holiday in Phu Quoc with the world\'s longest over-sea cable car ride to Hon Thom Island, VinWonders theme park, and Grand World\'s Venice-style canal shows."}]');

