-- Dumping data for table `faqs` (4 rows)
INSERT INTO `faqs` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (1, 'Can I customize my tour package according to my dates and budget?', 'Absolutely! Every itinerary at Golden Travels is 100% customizable. You can adjust the number of days, hotel category (4/5), sightseeing activities, private transfers, and meal plans according to your exact preference.', 1, 1, '2026-10-12 07:31:39', '2026-10-17 06:47:20');
INSERT INTO `faqs` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (2, 'How does Golden Travels assist with visas and documentation?', 'Our dedicated visa concierge team provides end-to-end documentation assistance, appointment scheduling, cover letter drafting, and biometric guidance with an industry-leading 99.2% approval success rate.', 2, 1, '2026-10-12 07:31:39', '2026-10-12 07:31:39');
INSERT INTO `faqs` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (3, 'What kind of support is provided while traveling on the trip?', 'You will have access to a 24/7 dedicated on-trip concierge manager on WhatsApp and phone. From flight updates to local driver coordination and emergency assistance, our team is always just a text away.', 3, 1, '2026-10-12 07:31:39', '2026-10-12 07:31:39');
INSERT INTO `faqs` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (4, 'What are the payment terms and refund policies?', 'We offer flexible payment milestone plans with transparent pricing. You can book your package with an initial deposit, and the balance can be paid in convenient installments before departure. Zero hidden charges guaranteed.', 4, 1, '2026-10-12 07:31:39', '2026-10-12 07:31:39');

