INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (1, 'rann-utsav-kutch', 'RANN UTSAV – The Tent City & White Desert', 'Rann Utsav (Kutch)', 'DOMESTIC', 'desert', 'Gujarat (Kutch)', 'Dhordo & Bhuj, Kutch, Gujarat', 'Bhuj, Dhordo & Dholavira', '4 Days | 3 Nights', 3, 4, 'Cultural Festival', '/assets/images/packages/rann-kutch.jpg', '[{"src":"/assets/images/packages/rann-kutch.jpg","title":"Sunset at White Rann"},{"src":"/assets/images/tour/tour-details3.jpg","title":"The Tent City, Dhordo"},{"src":"/assets/images/destination/des1.jpg","title":"Road Through Heaven, Dholavira"},{"src":"/assets/images/tour/1.jpg","title":"Kutch Craft Village & Haat"},{"src":"/assets/images/slide/slide1.jpg","title":"Cultural Folk Dances Under the Stars"}]', '["family","couple","friends","solo","seniors"]', '["The Tent City, Dhordo Luxury Stay","White Rann Sunset Excursion","Kala Dungar & Gandhi nu Gam Excursion","Dholavira & Road Through Heaven Tour","All Meals & High Tea Included","AC Coach Transfers from Bhuj"]', '["Rann Utsav","Kutch","Gujarat","White Desert","The Tent City","Dhordo","Bhuj","Dholavira","Kala Dungar","Cultural","Domestic","India"]', 'One of the popular events that is organized in Gujarat and is a major crowd puller from across the country and the world is the Rann Utsav. This is regarded as a celebration of life, culture, and the festivities of Kutch. The entire event is spread across 4 months which sees a riot of colours spread over the barren lands. The entire event offers an experience of diverse traditions as well as the taste of generous hospitality of the people from Kutch. The beautiful White Desert welcomes one and all and the sight of a full moon night during the entire period can be breathtaking.\n\nThe 4 months sees endless cycle of dances backed by century-old traditions that have been there for centuries. The colourful fair spread across the beach area or the lake swings which are placed on the lake banks add to the marvellous experience for flamboyancy. It embarks an ideal occasion for being part of the region’s culture and experiences its uniqueness which is second to none in terms of celebration of life.\n\nThe entire Rann Utsav also offers host of other activities to indulge in which expands across Camel Rides, Bird Watching, Pool Table, Paramotoring, Giant Chess, Archery, etc. The entire event will definitely be worth an experience of a lifetime.', '[{"day":"Day 1","title":"Arrival at Rann Utsav, The Tent City, Dhordo from Bhuj","loc":"Bhuj to The Tent City, Dhordo","meals":"Lunch, High Tea & Dinner Included","desc":"Welcome and transfer from Bhuj Airport/Railway Station to The Tent City, Dhordo. Witness the spellbinding sunset at White Desert.","schedule":["12:30 PM onwards: Welcome and check-in.","12:30 PM to 02:30 PM: Enjoy delicious lunch at the respective Dining Area.","02:30 PM to 04:30 PM: Leisure time / activities at Skyzilla, Club House, Craft Market/Haat, Various Selfie Points, Rejuvenation Center, Art Gallery, Live Demonstration Area of Kutch Craft and many others.","04:00 PM to 05:00 PM: High Tea.","05:00 PM to 05:30 PM: Visit the Sunset Point and the breathtaking White Rann to witness the setting sun. Transfers will be arranged by bus, camel cart, or a combination of both.","07:00 PM to 07:30 PM: Return transfer to Rann Utsav - The Tent City, Dhordo.","07:30 PM to 10:00 PM: Dinner at the respective Dining Area.","09:00 PM to 10:30 PM: Enjoy the culture of Kutch with entertaining activities at the Cultural Activity Area."],"image":"/assets/images/packages/rann-kutch.jpg"},{"day":"Day 2","title":"Excursion to Kala Dungar & Kutch Craft Village","loc":"Kala Dungar (Black Hill) & Gandhi nu Gam","meals":"Morning Tea, Breakfast, Lunch & Dinner Included","desc":"Complimentary excursion to Kala Dungar (highest point of Kutch) and authentic handicraft village Gandhi nu Gam en route.","schedule":["06:00 AM to 06:30 AM: Morning tea.","07:30 AM to 10:00 AM: Breakfast at the respective Dining Area.","10:00 AM to 12:30 PM: Leisure time / activities at Skyzilla, Club House, Craft Market/Haat, Selfie Points, Rejuvenation Center, Art Gallery and Kutch Craft demonstrations.","12:30 PM to 02:30 PM: Lunch at the respective Dining Area.","02:30 PM to 03:00 PM: Departure for Kala Dungar.","03:00 PM to 07:30 PM: Complimentary tour to Kala Dungar (Black Hill), the highest point of Kutch. Visit the handicraft village \'Gandhi nu Gam\' en route. Tea/coffee and complimentary refreshments will be served.","07:30 PM to 10:00 PM: Dinner at the respective Dining Area.","09:00 PM to 10:30 PM: Cultural activities at the Cultural Activity Area."],"image":"/assets/images/destination/des3.jpg"},{"day":"Day 3","title":"Road Through Heaven & Dholavira UNESCO World Heritage Site","loc":"Road Through Heaven & Dholavira Excavations","meals":"Morning Tea, Breakfast, Lunch, Refreshments & Dinner Included","desc":"Experience the scenic Road Through Heaven, Harappan civilization archaeological museum and ancient water systems at Dholavira.","schedule":["06:00 AM to 06:30 AM: Morning tea.","06:30 AM to 07:30 AM: Yoga session in the dedicated Activity Area.","07:30 AM to 10:00 AM: Breakfast at the respective Dining Area.","10:00 AM to 12:30 PM: Leisure time and indoor activities at Skyzilla, Club House, Craft Market/Haat, Curated Content Creation Zones, Rejuvenation Center, Art Gallery and Kutch Craft demonstration area.","12:30 PM to 01:30 PM: Lunch at the respective Dining Area.","01:30 PM: Depart for Dholavira (approximately 105 km, around 2 hours travel). Experience the scenic Road Through Heaven. Tea/coffee and light refreshments will be served during the journey.","03:30 PM to 05:30 PM: Visit the Archaeological Museum and Dholavira Excavation Site. Discover its urban planning, water management systems and archaeological heritage. (Museum remains closed every Friday).","05:30 PM to 06:00 PM: Tea/coffee and light refreshments during the journey.","06:00 PM to 06:45 PM: Sunset along the Road Through Heaven.","07:00 PM to 08:30 PM: Return to Rann Utsav - The Tent City, Dhordo.","08:30 PM to 10:00 PM: Dinner at the respective Dining Area."],"image":"/assets/images/destination/des1.jpg"},{"day":"Day 4","title":"Swaminarayan Temple, Kutch Museum & Bhuj Departure","loc":"Dhordo to Bhuj","meals":"Morning Tea & Breakfast Included","desc":"Morning yoga, hearty breakfast, checkout from Tent City, followed by complimentary sightseeing at Swaminarayan Temple and Kutch Museum before drop at Bhuj.","schedule":["06:00 AM to 06:30 AM: Morning tea.","06:30 AM to 07:30 AM: Yoga session in the dedicated Activity Area.","07:30 AM to 09:30 AM: Breakfast at the respective Dining Area.","09:30 AM: Check-out from Rann Utsav - The Tent City, Dhordo.","10:00 AM: Bus departure for Bhuj.","11:30 AM to 02:00 PM: Complimentary sightseeing at Swaminarayan Temple and Kutch Museum. (Kutch Museum remains closed on Wednesday). Drop-off at Bhuj Airport / Railway Station."],"image":"/assets/images/tour/1.jpg"}]', '["Pick-up and drop-off available from Bhuj Airport or Bhuj Railway Station by AC Coach at scheduled timings.","Accommodation in premium tents at Rann Utsav - The Tent City, Dhordo.","All meals as per schedule: Morning tea, breakfast, lunch, high tea, evening refreshments, and grand dinners.","Visit to the Sunset Point and breathtaking White Rann with bus / camel cart transfers.","Complimentary excursion tour to Kala Dungar (Black Hill) and Gandhi nu Gam handicraft village with refreshments.","Scenic drive through the famous \'Road Through Heaven\' and excursion to Dholavira Harappan Excavation Site & Museum.","Complimentary Bhuj sightseeing: Swaminarayan Temple and Kutch Museum.","Daily morning yoga sessions and vibrant evening cultural folk entertainment at the Cultural Activity Area.","Access to Skyzilla, Club House, Craft Haat, Art Gallery, and Live Kutch Craft demonstration zones."]', '["All rates are exclusive of applicable taxes and charged as per prevailing rates.","Airfare / Train fare to and from Bhuj.","Adventure sports activities such as Paramotoring, ATV rides, etc.","Personal, incidental, and other expenses not mentioned in the inclusions.","Personal services provided by operators at Tent City (rejuvenation centre, shopping at Haat).","Special transfers arranged outside the scheduled AC coach timings."]', '["1. All rates are exclusive of applicable taxes and will be charged as per prevailing rates.","2. In case of cancellation of flights, trains or any mode of transportation, the booking amount is not refundable.","3. Pick-up and drop-off are available only from Bhuj Airport or Bhuj Railway Station by AC Coach at scheduled timings.","4. The package voucher and government-approved photo ID proof, such as Aadhaar, must be presented at check-in. Foreign nationals must provide a valid passport and visa. PAN card is not accepted as valid photo ID.","5. In case of delayed arrival of a train or flight, guests will be transferred to Tent City, Dhordo in the next available transfer.","6. Guests arriving late will not be entitled to missed meals or activities.","7. Guests arriving early may have to wait in the waiting lounge until their tent is available.","8. Adventure sports such as paramotoring and ATV rides involve physical and mental risks, including serious injury or loss of life. Guests may be required to sign an indemnity. Management assumes no responsibility for the activities or negligence of operators.","9. Services provided by operators at Tent City, including travel agents, rejuvenation centre, travel desk, adventure sports and Haat shopping, are at the guest\'s discretion. Management assumes no responsibility for these services.","10. Guests must arrive at boarding points at least 15 minutes before departure. If they miss the scheduled bus, they must arrange their own transportation.","11. Transfer timings to and from White Rann and Kala Dungar may vary according to sunset timings and climatic conditions.","12. Guests are responsible for any loss or damage to Tent City property caused by themselves or persons for whom they are responsible.","13. Vehicle AC temperatures will be maintained according to the comfort of the majority of guests.","14. Date change charges: 15% of the total booking amount.","15. Primary guest name change charges: 5% of the total booking amount.","16. Room category downgrade charges: 5% of the total booking amount.","17. For amendments or changes, email: booking.rann@evokeexperiences.in","18. Date changes are allowed only once and at least 72 hours before check-in. Requests made within 72 hours are treated as cancellations.","19. Personal, incidental and other expenses not mentioned in the inclusions must be borne by the guest.","20. Management is not responsible for loss of personal belongings or valuables.","21. Transfer vehicles will not remain exclusively at the disposal of guests.","22. The itinerary is indicative and may change at management\'s discretion.","23. Late or early check-out transfers must be arranged at reception and will be chargeable.","24. White Rann is a natural formation; management is not responsible for changes caused by nature.","25. All tents are strictly non-smoking areas.","26. Guests must follow house rules and applicable laws.","27. Management may cancel reservations due to government events, visits or natural calamities. Alternative dates or an accommodation refund may be offered, but transportation expenses are not covered.","28. Management\'s liability for baggage loss due to fire or similar incidents is limited to INR 50,000 per tent. Guests may purchase insurance.","29. Management is not liable for minor baggage wear and tear, including cuts, scratches, broken wheels or dents.","30. Pets are not allowed inside Tent City.","31. If the property must close due to government regulations, 100% of the accommodation booking amount will be refunded. Transportation expenses are not covered.","32. Guests experiencing COVID symptoms at Tent City will be assessed by the medical team and guided to a hospital if required.","33. Guests experiencing COVID symptoms at Bhuj Lounge may have their arrival date amended subject to availability. Any rate difference must be paid by the guest.","34. Disputes are subject to Ahmedabad jurisdiction only.","35. All rights are reserved by management."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Rann Utsav Kutch Tour Package | The Tent City & White Desert | Golden Travels', 'Experience Rann Utsav at The Tent City Dhordo, Gujarat. 4 Days / 3 Nights package with White Rann sunset, Dholavira UNESCO tour, meals & luxury AC tent stay.', 'rann utsav kutch, white desert gujarat, tent city dhordo, rann utsav package, kutch tour packages, golden travels', 'http://localhost:3000/tour/rann-utsav-kutch', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (2, 'rajasthan-royal-heritage', 'RAJASTHAN PROGRAM – Jaipur, Bikaner, Jaisalmer & Jodhpur', 'Royal Rajasthan', 'DOMESTIC', 'heritage', 'Rajasthan', 'Jaipur, Bikaner, Jaisalmer, Sam & Jodhpur', '4 Royal Cities & Desert Camp', '7 Days | 6 Nights', 6, 7, 'Royal Forts & Palaces', '/assets/images/packages/rajasthan-fort.jpg', '[{"src":"/assets/images/packages/rajasthan-fort.jpg","title":"Amber Fort & Royal Palaces, Jaipur"},{"src":"/assets/images/tour/5.jpg","title":"Sam Sand Dunes Camel Safari, Jaisalmer"},{"src":"/assets/images/travel-list/11.jpg","title":"Junagarh Fort & Rampuria Havelis, Bikaner"},{"src":"/assets/images/tour/1.jpg","title":"Mehrangarh Fort & Jaswant Thada, Jodhpur"},{"src":"/assets/images/travel-list/12.jpg","title":"Gadisar Lake & Golden City Havelis"},{"src":"/assets/images/slide/slide3.jpg","title":"Traditional Kalbelia Folk Music Night"}]', '["family","couple","friends","seniors","solo"]', '["All Transfers & Sightseeing Transport","Sam Sand Dunes Desert Camp Stay","Camel Safari in Thar Desert Dunes","Rajasthani Folk Dance & Kalbelia Show","Amber, Junagarh & Mehrangarh Forts","All Tolls, Fuel & Interstate Taxes Included"]', '["Rajasthan","Jaipur","Bikaner","Jaisalmer","Jodhpur","Sam Sand Dunes","Amber Fort","Mehrangarh","Camel Safari","Desert Camp","Domestic","India"]', 'Experience the majestic royal heritage of Rajasthan across four legendary imperial cities and the heart of the Thar Desert. From the grand pink facades and hill fortresses of Jaipur to the intricately carved stone havelis of Bikaner, the golden living fort of Jaisalmer, and the towering cobalt walls of Mehrangarh in Jodhpur, this 7-day handcrafted journey delivers the definitive royal Indian holiday.\n\nEnjoy unforgettable nights under starry desert skies at Sam Sand Dunes, with authentic camel safaris across rippling sands, energetic Kalbelia dance performances, and traditional Rajasthani cuisine served with royal hospitality.', '[{"day":"Day 01","title":"Arrive Jaipur – Welcome to the Pink City","loc":"Jaipur","meals":"Dinner Included","desc":"Arrive in Jaipur and meet our representative at the airport/railway station. Assisted transfer to the hotel. Check-in formalities and relax after journey. Evening free to explore local markets or enjoy a traditional Rajasthani dinner at leisure. Overnight stay: Jaipur.","image":"/assets/images/packages/rajasthan-fort.jpg"},{"day":"Day 02","title":"Jaipur Full-Day Sightseeing – Forts, Palaces & Bazaars","loc":"Amber Fort, Jal Mahal, City Palace, Hawa Mahal","meals":"Breakfast Included","desc":"Full-day sightseeing of Jaipur: Amber Fort (hilltop fort with Rajput architecture), Jal Mahal (palace amidst Man Sagar Lake), City Palace (former royal residence with museums), Jantar Mantar (astronomical observatory), photo stop at iconic Hawa Mahal, and explore colourful Johari Bazaar & Bapu Bazaar. Overnight stay: Jaipur.","image":"/assets/images/travel-list/11.jpg"},{"day":"Day 03","title":"Jaipur to Bikaner – Historic Desert Gateway (~330 km / 6 hrs)","loc":"Bikaner","meals":"Breakfast Included","desc":"After breakfast, check out and drive towards Bikaner, the historic desert city. Check-in at hotel. Sightseeing includes Junagarh Fort (decorated palaces, courtyards & intricate interiors), magnificent Rampuria Havelis facades, and the historic old city markets. Overnight stay: Bikaner.","image":"/assets/images/travel-list/12.jpg"},{"day":"Day 04","title":"Bikaner to Jaisalmer – The Golden City (~330 km / 6 hrs)","loc":"Jaisalmer","meals":"Breakfast Included","desc":"After breakfast, check out and drive towards Jaisalmer in the Thar Desert. Check in at hotel and relax. In the evening, visit historic Gadisar Lake surrounded by shrines and carved structures, and explore the vibrant atmosphere of Jaisalmer\'s old city. Overnight stay: Jaisalmer.","image":"/assets/images/destination/des4.jpg"},{"day":"Day 05","title":"Jaisalmer Havelis & Sam Sand Dunes Desert Camp","loc":"Jaisalmer Fort & Sam Sand Dunes","meals":"Breakfast & Camp Dinner Included","desc":"Morning sightseeing: Jaisalmer Fort (living fort), Jain Temples, Patwon Ki Haveli, Nathmal Ki Haveli, and Salim Singh Ki Haveli. Drive to Sam Sand Dunes and check in at the desert camp. Evening camel safari across golden dunes, stunning sunset, traditional Rajasthani cultural folk music & Kalbelia dance show followed by dinner. Overnight stay: Desert camp at Sam.","image":"/assets/images/tour/5.jpg"},{"day":"Day 06","title":"Sam Dunes to Jodhpur – The Blue City (~310 km / 6 hrs)","loc":"Jodhpur","meals":"Breakfast Included","desc":"After breakfast, check out from desert camp and drive towards Jodhpur. Check-in at hotel. Sightseeing includes magnificent Mehrangarh Fort with panoramic views of the blue city, marble cenotaph Jaswant Thada, Umaid Bhawan Palace Museum, and Clock Tower / Sardar Market for local handicrafts. Overnight stay: Jodhpur.","image":"/assets/images/tour/1.jpg"},{"day":"Day 07","title":"Jodhpur Departure","loc":"Jodhpur Airport / Railway Station","meals":"Breakfast Included","desc":"After breakfast, check out from hotel. Depending on departure schedule, free time for last-minute shopping or leisure in Jodhpur. Transfer to Jodhpur Airport/Railway Station for onward journey.","image":"/assets/images/slide/slide3.jpg"}]', '["All transfers, city tours and transport services as per the itinerary.","Road taxes, parking fees, fuel charges and interstate taxes.","Camel ride at Jaisalmer across Sam Sand Dunes.","Desert camp accommodation with cultural folk music, Kalbelia dance & dinner."]', '["Monument entrance fees.","English-speaking guide.","Elephant ride at Amber Fort, Jaipur.","Jeep ride at Amber Fort, Jaipur.","Dune bashing in Jaisalmer.","Boat ride at Udaipur.","Personal expenses such as tipping, laundry, telephone/fax calls, alcoholic beverages, camera/video camera fees at monuments, medical expenses and airport departure tax.","Any services not mentioned in the inclusions.","Airfare / train fare.","Expenses caused by circumstances beyond control, such as roadblocks, accidents, medical evacuations, train delays or rescheduling.","Visa fees, insurance fees and tips to hotel staff, local guides and drivers.","Meals apart from those mentioned in the itinerary.","Any other expenses not listed in the inclusions."]', '["1. All sightseeing and transfers will be provided as per the pre-confirmed itinerary only.","2. Normal sightseeing timings are from 07:30 hrs to 19:30 hrs.","3. The vehicle is not at disposal and will be provided according to the pre-decided itinerary.","4. All commercial vehicles are required to have speed governors capped at 80 kmph.","5. In Delhi, Red Fort remains closed every Monday.","6. In Agra, Taj Mahal remains closed every Friday.","7. All monuments in Rajasthan will be closed on Dhulandi, the day after Holi.","8. Ranthambore National Park and Sariska National Park will be closed from 1 July to 30 September."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:12:23', 'Rajasthan Royal Heritage Tour | Jaipur, Jodhpur, Jaisalmer & Bikaner | Golden Travels', 'Explore royal forts, palaces, and Thar desert dunes of Rajasthan across Jaipur, Bikaner, Jaisalmer & Jodhpur. Handcrafted luxury heritage holiday with Golden Travels.', 'rajasthan tour package, jaipur jodhpur jaisalmer trip, bikaner heritage tour, thar desert safari, rajasthan holiday packages', 'http://localhost:3000/tour/rajasthan-royal-heritage', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (3, 'puri-bhubaneswar-heritage', 'PURI & BHUBANESWAR PROGRAM – Temples, Konark & Coastal Odisha', 'Puri & Odisha', 'DOMESTIC', 'spiritual', 'Odisha', 'Bhubaneswar, Puri & Konark, Odisha', 'Puri, Konark & Bhubaneswar', '5 Days | 4 Nights', 4, 5, 'Spiritual & UNESCO', '/assets/images/packages/puri-temple.jpg', '[{"src":"/assets/images/packages/puri-temple.jpg","title":"Konark Sun Temple (Black Pagoda)"},{"src":"/assets/images/tour/tour-details.jpg","title":"Jagannath Temple & Puri Sea Beach"},{"src":"/assets/images/destination/des4.jpg","title":"Dhauli Shanti Stupa (Peace Pagoda)"},{"src":"/assets/images/tour/1.jpg","title":"Lingaraj Temple & Mukteswar Architecture"},{"src":"/assets/images/destination/des5.jpg","title":"Khandagiri & Udayagiri Ancient Caves"},{"src":"/assets/images/slide/slide1.jpg","title":"Chandrabhaga Golden Sand Beach"}]', '["seniors","family","couple","solo","friends"]', '["AC Innova Crysta Private Sightseeing & Transfers","Accommodation on Double-Sharing Basis","4 Daily Breakfasts Included","Certified Guide at Konark Sun Temple","Jagannath Temple & Puri Golden Sea Beach","Tolls, Parking, Driver Bata & GST Included"]', '["Puri","Bhubaneswar","Konark","Sun Temple","Jagannath Temple","Odisha","Chandrabhaga Beach","Dhaulagiri","Lingaraj","Spiritual","Domestic","India"]', 'Discover the divine spiritual energy and ancient architectural wonders of Odisha. Home to Lord Jagannath\'s sacred Dham, the 13th-century UNESCO World Heritage Konark Sun Temple (famed as the Black Pagoda), the serene shores of Chandrabhaga Beach, and the timeless stone sanctuaries of Bhubaneswar — the City of Temples.\n\nFrom the vibrant applique artisan community of Pipili to Emperor Ashoka\'s Peace Pagoda at Dhaulagiri and the rock-cut caves of Khandagiri and Udayagiri, this 5-day private pilgrimage and coastal exploration offers unforgettable cultural depth and peace of mind.', '[{"day":"Day 1","title":"Bhubaneswar to Puri – Arrival and Transfer","loc":"Bhubaneswar Airport to Puri","meals":"Welcome Stay","desc":"Arrive at Bhubaneswar Airport. Meet and greet by our representative. Private transfer to holy coastal town Puri. Check-in to hotel, relax and enjoy your overnight stay at Puri.","image":"/assets/images/tour/tour-details.jpg"},{"day":"Day 2","title":"Puri Local Sightseeing – Sacred Temples & Golden Beach","loc":"Jagannath Temple & Puri Beach","meals":"Breakfast Included","desc":"After breakfast by 8:30 AM, proceed for full-day sightseeing: Sri Jagannath Temple (one of the four sacred Dhams; only Hindus permitted inside), Sakshigopal Temple, Golden Sea Beach, and free time for beachside shopping. Return to hotel. Overnight stay: Puri.","image":"/assets/images/packages/puri-temple.jpg"},{"day":"Day 3","title":"Puri to Bhubaneswar via Konark Sun Temple & Dhaulagiri","loc":"Konark, Pipili, Dhauli & Bhubaneswar","meals":"Breakfast Included","desc":"After breakfast, check out and drive to Bhubaneswar. En route visit Chandrabhaga Beach, the world-renowned 13th-century Konark Sun Temple (Black Pagoda, with dedicated guide), Pipili applique artisan village, and Dhaulagiri Peace Pagoda (where Emperor Ashoka renounced violence). Check in at Bhubaneswar hotel. Freshen up and visit Lingaraj Temple (dedicated to Harihara), Mukteswar Temple (Gem of Odisha Architecture), and Kedargouri Temple. Overnight stay: Bhubaneswar.","image":"/assets/images/destination/des4.jpg"},{"day":"Day 4","title":"Bhubaneswar Full-Day Sightseeing – Caves, Temples & Crafts","loc":"Bhubaneswar City & Ekamra Haat","meals":"Breakfast Included","desc":"After breakfast, visit ISKCON Temple, rock-cut Khandagiri and Udayagiri Caves, and Kalabhumi Art & Craft Museum (closed on Monday). After lunch, visit Ram Mandir, Parsurameswar Temple, Ananta Basudev Temple, Swamy Venkateswara Temple, State Museum (closed on Monday), and enjoy shopping at Ekamra Haat. Overnight stay: Hotel in Bhubaneswar.","image":"/assets/images/destination/des5.jpg"},{"day":"Day 5","title":"Bhubaneswar – Departure with Sweet Memories","loc":"Bhubaneswar Airport","meals":"Breakfast Included","desc":"After breakfast, check out from the hotel and transfer to Bhubaneswar Airport for your onward journey with sweet memories of Odisha.","image":"/assets/images/tour/1.jpg"}]', '["Meet and greet by our representative at Bhubaneswar Airport.","Accommodation on a double-sharing basis.","Meal plan: 4 breakfasts.","Pick-up, drop-off and sightseeing by dedicated AC Innova Crysta as per the itinerary.","Toll, parking, night halt, driver bata and fuel charges.","Authorised guide service at Konark Sun Temple.","One 500 ml packaged drinking water bottle per person per day in the vehicle.","All taxes / GST included."]', '["Train fare / airfare.","Any kind of monument or museum entry fees.","Personal expenses such as telephone, laundry and beverages (both alcoholic and non-alcoholic).","Standing AC.","Early check-in / late check-out.","Anything not mentioned in the inclusions."]', '["1. ID and address proof are mandatory for every guest.","2. Once an e-invoice is generated, further modification is not permitted.","3. For a single bill settlement, a maximum cash deposit of Rs. 2,00,000/- can be accepted in the account with PAN card details.","4. Cash deposits below Rs. 50,000/- do not require a PAN card."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Puri Jagannath Temple & Bhubaneswar Tour Package | Konark Sun Temple | Golden Travels', 'Book Puri and Bhubaneswar heritage tour covering Jagannath Temple, UNESCO Konark Sun Temple, Chilika Lake and coastal Odisha with private transfers.', 'puri tour package, jagannath temple visit, konark sun temple trip, bhubaneswar tourist places, odisha holiday package', 'https://goldentravels.in/tour/puri-bhubaneswar-heritage', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (4, 'andaman-islands-escape', 'ANDAMAN – Port Blair, Havelock & Neil Island Escapade', 'Andaman Islands', 'DOMESTIC', 'island', 'Andaman & Nicobar', 'Port Blair, Havelock Island & Neil Island', '3 Tropical Islands', '6 Days | 5 Nights', 5, 6, 'Tropical Beach Paradise', '/assets/images/packages/andaman-beach.jpg', '[{"src":"/assets/images/packages/andaman-beach.jpg","title":"Radhanagar Beach Turquoise Waters, Havelock"},{"src":"/assets/images/tour/tour-details.jpg","title":"Elephant Beach Coral Snorkelling"},{"src":"/assets/images/destination/img2.jpg","title":"Historic Cellular Jail & Light & Sound Show"},{"src":"/assets/images/tour/4.jpg","title":"Natural Coral Bridge (Howrah Bridge), Neil Island"},{"src":"/assets/images/travel-list/6.jpg","title":"Bharatpura & Laxmanpura Sunset Beaches"},{"src":"/assets/images/tour/2.jpg","title":"Private Catamaran Ferry Cruise (Makruzz)"}]', '["couple","family","friends","solo","seniors"]', '["Private Catamaran Premium Ferries (Makruzz / Nautika)","Radhanagar Blue Flag Beach & Elephant Beach","Cellular Jail Entry & 3D Light and Sound Show Tickets","Elephant Island Speedboat Charges Included","Neil Island Natural Coral Bridge & Coral Beaches","AC Vehicle Transfers Across All Islands"]', '["Andaman","Port Blair","Havelock","Neil Island","Radhanagar Beach","Elephant Beach","Cellular Jail","Scuba","Snorkeling","Beaches","Domestic","India"]', 'Surround yourself with the crystal turquoise waters, pristine white sands, and lush tropical forests of the Andaman & Nicobar archipelago. This comprehensive 6-day island journey links the historic city of Port Blair with the postcard-perfect shores of Havelock Island and the tranquil coral wonders of Neil Island via premium high-speed catamaran ferries.\n\nRelive Indian history through the stirring 3D Light and Sound show at Cellular Jail, swim in the calm azure waves of Asia\'s famed Blue Flag Radhanagar Beach, snorkel amidst vibrant coral reefs at Elephant Beach, and marvel at the naturally sculpted limestone arch of Howrah Bridge on Neil Island.', '[{"day":"Day 1","title":"Port Blair Arrival – Cellular Jail, Tiranga Park & Corbyn\'s Cove Beach","loc":"Port Blair","meals":"Welcome Stay","desc":"Meet and greet at Port Blair Airport and transfer to hotel. In late afternoon, visit historic Cellular Jail (museum & 360° city view). Proceed to palm-fringed Corbyn\'s Cove Beach via Tiranga Park photo stop. Enjoy Sea Kart ride and water sports at additional cost. Overnight stay: Port Blair.","image":"/assets/images/destination/img2.jpg"},{"day":"Day 2","title":"Port Blair to Havelock Island – Radha Nagar Beach","loc":"Havelock Island","meals":"Breakfast Included","desc":"Transfer to Port Blair Jetty for private catamaran ferry to Havelock. Meet local representative and transfer to resort. In afternoon, visit world-famous Blue Flag-certified Radha Nagar Beach for swimming and relaxing sunset. (Ferry: Port Blair to Havelock – Private Catamaran Ferry, Shared Basis, Premium). Overnight stay: Havelock.","image":"/assets/images/packages/andaman-beach.jpg"},{"day":"Day 3","title":"Havelock – Elephant Beach (Coral Snorkelling) & Kalapathar Beach","loc":"Elephant Beach & Kalapathar Beach","meals":"Breakfast Included","desc":"Proceed by shared boat to Elephant Beach (Coral Beach), celebrated for snorkelling, jet skiing, banana rides and sea walks. Boat operators usually offer complimentary 5-minute snorkelling (weather permitting). Later visit peaceful Kala Pathar Beach with clear aqua water and dense forest backdrop. Overnight stay: Havelock.","image":"/assets/images/tour/tour-details.jpg"},{"day":"Day 4","title":"Havelock to Neil Island – Bharatpura, Laxmanpura & Natural Bridge","loc":"Neil Island","meals":"Breakfast Included","desc":"Proceed to jetty for premium catamaran ferry to Neil Island. Check in at resort. Afternoon sightseeing: Bharatpura Beach (shallow waters, boat tours), Laxmanpura Beach (sunset views), and Natural Coral Bridge (Howrah Bridge, best viewed during low tide). (Ferry: Havelock to Neil Island – Private Catamaran, Premium). Overnight stay: Neil Island.","image":"/assets/images/tour/4.jpg"},{"day":"Day 5","title":"Neil Island to Port Blair – 3D Light & Sound Show at Cellular Jail","loc":"Port Blair","meals":"Breakfast Included","desc":"Ferry transfer from Neil Island back to Port Blair. Check in to hotel. In the evening, witness the stirring 3D Light and Sound Show at Cellular Jail recounting the heroic saga of Kalapani freedom fighters. (Ferry: Neil Island to Port Blair – Private Catamaran, Premium). Overnight stay: Port Blair.","image":"/assets/images/travel-list/6.jpg"},{"day":"Day 6","title":"Port Blair Departure","loc":"Port Blair Airport","meals":"Breakfast Included","desc":"Breakfast at hotel and assisted transfer to Port Blair Airport. (Airport experiences heavy traffic; reporting 2 hours prior is recommended). Tour concludes with cherished tropical island memories.","image":"/assets/images/tour/2.jpg"}]', '["Meet-and-greet services by local representatives at airport and jetties.","Meal plan as mentioned in the itinerary (daily breakfasts).","Airport and ferry terminal transfers in an air-conditioned vehicle.","All sightseeing, including entry fees, as per the itinerary in an air-conditioned vehicle.","Inter-island ferry transfers by private catamaran ferries (Makruzz preferred, Nautika, Green Ocean, ITT Majestic or similar, subject to availability).","Elephant Beach boat charge.","Cellular Jail 3D Light and Sound Show confirmed tickets."]', '["Airfare to/from Port Blair.","5% GST.","Vehicle services beyond the itinerary and disposal arrangements.","Personal expenses, optional tours, extra meals, water sports, and vehicles for dinner.","Anything not mentioned in the inclusions."]', '["1. Tour timings may change depending on slot availability, ticket bookings and practical requirements. Final timings will be advised by the local representative.","2. Standard hotel check-in/check-out timings are generally between 08:30 AM and 10:00 AM. Early check-in and late check-out are subject to availability and hotel discretion.","3. For early ferry departures, guests may request packed or cold breakfast, subject to hotel policy.","4. Carry required medicines, especially for seasickness or migraine.","5. Paytm and GPay are accepted at many places, but guests are advised to carry enough cash because Havelock and Neil Island have limited ATMs.","6. Liquor is available on the islands, but preferred brands may not be available.","7. Vehicles are exclusive to guests but are not at disposal. Vehicles may change every day and by sector.","8. Vehicles for lunch, dinner or other purposes incur additional charges. At least two hours\' prior notice is required.","9. Vehicles will wait a maximum of 15 minutes from the scheduled pick-up time.","10. Neil Island has a shortage of vehicles due to environmental regulations, so additional waiting time may occur.","11. Cellular Jail Light and Sound Show e-tickets are non-transferable, non-cancellable and non-refundable, including in cases of bad weather or unforeseen circumstances.","12. Carry changing clothes and towels when visiting beaches. Wet clothes are not permitted inside vehicles.","13. The itinerary may be rearranged due to bad weather. Changes in hotel or ferry operations may incur extra charges.","14. Airtel, Vodafone and BSNL work across the Andaman Islands. Jio works only in Port Blair, and internet connectivity is poorer than on the mainland.","15. Luggage allowance: maximum 20 kg plus one personal item weighing no more than 3 kg per person.","16. Andaman has tropical weather, and sunshine and rain are unpredictable. Carrying an umbrella is recommended.","17. Guests are encouraged to carry a reusable bottle to help reduce plastic waste. Only 2-litre water bottles are available for purchase across the islands.","18. All extras not mentioned above must be paid directly to the hotel/service provider.","19. The minimum age for diving is 12. Divers over 50 must produce a medical clearance certificate for scuba diving/sea walking.","20. The islands are remote, so facilities and infrastructure cannot be compared with those on the mainland."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Andaman Island Tour Package | Port Blair, Havelock & Neil Island | Golden Travels', 'Unwind in Andaman turquoise waters: Radhanagar Beach, Cellular Jail sound & light show, Elephant Beach snorkeling & luxury inter-island cruise transfers.', 'andaman tour package, havelock island trip, port blair holiday, neil island beach resort, andaman honeymoon package', 'https://goldentravels.in/tour/andaman-islands-escape', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (5, 'north-east-program', 'NORTH EAST PROGRAM – Meghalaya, Kaziranga & Assam', 'North East & Meghalaya', 'DOMESTIC', 'nature', 'Assam & Meghalaya', 'Shillong, Cherrapunjee, Kaziranga & Guwahati', '4 Scenic Destinations', '7 Days | 6 Nights', 6, 7, 'Waterfalls & Wildlife', '/assets/images/packages/northeast-hills.jpg', '[{"src":"/assets/images/packages/northeast-hills.jpg","title":"Cherrapunjee Waterfalls & Khasi Hills"},{"src":"/assets/images/tour/tour-details.jpg","title":"Kaziranga National Park Rhino Safari"},{"src":"/assets/images/slide/slide2.jpg","title":"Dawki Crystal Clear Umngot River"},{"src":"/assets/images/explore/9.jpg","title":"Mawlynnong Living Root Bridge"},{"src":"/assets/images/explore/10.jpg","title":"Phe Phe Falls & Krangshuri Azure Pools"},{"src":"/assets/images/tour/3.jpg","title":"Brahmaputra Evening Dinner Cruise, Guwahati"}]', '["family","friends","couple","solo","seniors"]', '["AC Force Urbania Private Vehicle for Entire Tour","MAP Meal Plan (Daily Breakfast & Dinner Included)","Kaziranga Elephant Safari & Jeep Safari Included","Brahmaputra River Dinner Cruise in Guwahati","Kamakhya Temple Darshan with Dedicated Priest","Cherrapunjee, Dawki, Mawlynnong & Jowai Tours"]', '["North East","Shillong","Cherrapunjee","Dawki","Mawlynnong","Jowai","Kaziranga","Guwahati","Assam","Meghalaya","Waterfalls","Wildlife","Domestic","India"]', 'Journey into India\'s most enchanting wonderland across the rolling clouds of Meghalaya and the untamed wilderness of Assam. Experience Cherrapunjee — the rain capital of the world — with roaring cascades like Nohkalikai and Seven Sisters Falls, explore the living-root bridges and cleanest village in Asia at Mawlynnong, glide along the crystal-transparent waters of the Umngot River in Dawki, and swim in the azure lagoons of Krangshuri and Phe Phe Falls in Jowai.\n\nIn Assam, encounter the majestic one-horned rhinoceros on both Elephant Safari and Jeep Safari through Kaziranga National Park, cruise the great Brahmaputra River under sunset skies, and receive divine blessings at the revered Kamakhya Temple with a dedicated priest.', '[{"day":"Day 01","title":"Guwahati to Shillong – Welcome to the Scotland of the East","loc":"Guwahati Airport to Shillong","meals":"Dinner Included","desc":"Arrival at Guwahati Airport at 05:25 PM. Meet our representative and enjoy a scenic private transfer to Shillong. Check in at hotel and unwind. Overnight stay: Shillong.","image":"/assets/images/packages/northeast-hills.jpg"},{"day":"Day 02","title":"Shillong – Cherrapunjee Excursion & Cascading Waterfalls","loc":"Cherrapunjee (Sohra)","meals":"Breakfast & Dinner Included","desc":"Full-day excursion to Cherrapunjee, the wettest place in the world. Visit Noh-ka-likai Falls, Dainthlen Falls, Seven Sister Falls, Cherrapunjee View Point, and ancient Mawsmai Limestone Cave. Return to Shillong, visiting Elephant Falls and panoramic Shillong Peak en route. Overnight stay: Shillong.","image":"/assets/images/tour/tour-details.jpg"},{"day":"Day 03","title":"Shillong – Mawlynnong Cleanest Village & Dawki Border","loc":"Mawlynnong & Dawki","meals":"Breakfast & Dinner Included","desc":"Excursion to Mawlynnong (Asia\'s cleanest village) and Dawki. Experience the iconic living-root bridge, boat ride on the crystal-clear Umngot River (at additional cost), and visit the peaceful Indo-Bangladesh Border. Return to Shillong. Overnight stay: Shillong.","image":"/assets/images/slide/slide2.jpg"},{"day":"Day 04","title":"Shillong – Jowai Excursion (Phe Phe & Krangshuri Falls)","loc":"Jowai, West Jaintia Hills","meals":"Breakfast & Dinner Included","desc":"After breakfast, proceed for a scenic day excursion to Jowai. Visit mesmerizing Phe Phe Falls and Krangshuri Falls, famous for their crystal-clear blue waters and natural jungle surroundings. Soak in the breathtaking Khasi countryside landscapes before driving back to Shillong. Overnight stay: Shillong.","image":"/assets/images/explore/9.jpg"},{"day":"Day 05","title":"Shillong to Kaziranga National Park","loc":"Shillong to Kaziranga","meals":"Breakfast & Dinner Included","desc":"After breakfast, visit Don Bosco Museum and peaceful Umiam Lake surrounded by pine-wooded hills. Transfer from Shillong to Kaziranga. In the evening, visit local Tea Gardens and the Kaziranga National Orchid & Biodiversity Park. Overnight stay: Kaziranga.","image":"/assets/images/tour/3.jpg"},{"day":"Day 06","title":"Kaziranga Safaris to Guwahati – Brahmaputra Dinner Cruise","loc":"Kaziranga to Guwahati","meals":"Breakfast & Cruise Dinner Included","desc":"Early morning thrilling Elephant Safari at Kaziranga National Park to spot one-horned rhinos, followed by an exhilarating Jeep Safari. Post safaris, transfer to Guwahati. In the evening, enjoy a grand Brahmaputra Dinner Cruise. Overnight stay: Guwahati.","image":"/assets/images/destination/des2.jpg"},{"day":"Day 07","title":"Guwahati – Kamakhya Temple Darshan & Departure","loc":"Guwahati Airport","meals":"Breakfast Included","desc":"After breakfast, check out from hotel. Visit the holy Kamakhya Temple with a dedicated priest for special darshan. Transfer to Guwahati Airport at 01:25 PM for flight home with unforgettable memories. Tour ends.","image":"/assets/images/explore/10.jpg"}]', '["All transfers and sightseeing as per the itinerary in one private AC Force Urbania (Note: AC will not operate in hill terrain).","Accommodation in 5 double rooms plus 1 child with extra bed/mattress, on MAP basis (Room + Breakfast + Dinner) at all destinations.","One elephant safari at Kaziranga National Park.","One jeep safari at Kaziranga National Park.","Brahmaputra River Dinner Cruise at Guwahati.","Kamakhya Temple special darshan with dedicated priest at Guwahati.","One litre of packaged drinking water per person per day.","Parking charges, toll tax and driver\'s allowance as per the itinerary."]', '["Personal expenses, tips, guide charges, entry fees, local taxis, camera charges, insurance and portage.","Additional meals, mineral water, soft drinks and hard drinks.","Airfare, train fare and bus fare.","5% GST.","Anything not included in the inclusions."]', '["1. Children below 5 years are complimentary.","2. Depending on guest arrival and departure times, the destination sequence may be changed.","3. Additional expenses caused by changes in oil prices, mishaps, landslides, strikes, political unrest and similar circumstances will be charged at actual cost directly to the guest.","4. The quoted rates are not a confirmation. Rates are subject to room and service availability at the time of reservation.","5. Rates are not valid during festive seasons, weekends and blackout dates.","6. Guests are requested to confirm as soon as possible to block the rooms.","7. The provider invites guests to request further information if required."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'North East Tour Package | Meghalaya, Kaziranga Safari & Assam | Golden Travels', 'Discover Meghalaya living root bridges, Cherrapunjee waterfalls, Dawki crystal river and Kaziranga rhino jeep safari with Golden Travels specialists.', 'north east tour package, meghalaya holiday, kaziranga national park safari, shillong cherrapunjee trip, assam meghalaya tour', 'https://goldentravels.in/tour/north-east-program', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (6, 'vietnam-beauty-of-vietnam', 'VIETNAM – Beauty of Vietnam', 'Vietnam Explorer', 'INTERNATIONAL', 'international', 'Vietnam (Hanoi, Halong, Danang, Phu Quoc)', 'Hanoi, Halong Bay, Danang, Hoi An & Phu Quoc', 'Hanoi, Ninh Binh, Halong Bay, Danang, Hoi An, Phu Quoc', '9 Days | 8 Nights', 8, 9, 'Bestseller', '/assets/images/packages/vietnam.jpg', '[{"src":"/assets/images/packages/vietnam.jpg","title":"Halong Bay Overnight Cruise & Emerald Waters"},{"src":"/assets/images/destination/3.jpg","title":"Tam Coc River Caves & Ninh Binh Karsts"},{"src":"/assets/images/travel-list/3.jpg","title":"Golden Bridge & Ba Na Hills Summit"},{"src":"/assets/images/tour/3.jpg","title":"Hoi An Ancient Lantern Town & Thu Bon River"},{"src":"/assets/images/travel-list/5.jpg","title":"Phu Quoc Tropical Islands & Coral Reefs"},{"src":"/assets/images/destination/des4.jpg","title":"Kiss Bridge Sunset Town, Phu Quoc"}]', '["family","couple","friends","solo"]', '["2 Nights Hanoi, 1 Night Halong Cruise, 2 Nights Danang, 3 Nights Phu Quoc","Overnight Luxury Cruise in Halong Bay with all meals, Tai Chi & kayaking","Ba Na Hills Cable Car, Golden Bridge & Hoi An Lantern Boat Ride","Ninh Binh Tam Coc Sampan River Cruise & Bich Dong Pagoda","Phu Quoc 3 Islands Snorkelling & Aquatopia Water Park Cable Car","Vinpearl Safari & VinWonders with Indian & International Meals"]', '["Vietnam","Hanoi","Halong Bay","Danang","Hoi An","Phu Quoc","Ninh Binh","Ba Na Hills","Golden Bridge","Vinpearl","International","Asia"]', 'Experience the breathtaking beauty of Vietnam on an unforgettable 9 Days / 8 Nights journey from the historic streets of Hanoi to the emerald waters of Halong Bay, the coastal charm of Danang, the UNESCO-listed lantern-lit town of Hoi An, and the tropical paradise of Phu Quoc Island.\n\nFrom cruising through towering limestone karsts on an overnight luxury cruise to walking across the world-famous Golden Bridge held by giant stone hands at Ba Na Hills, floating on a traditional sampan through Ninh Binh\'s river caves, and discovering exotic wildlife at Vinpearl Safari, this comprehensive itinerary delivers the ultimate blend of culture, nature, luxury, and authentic Indian and local dining.', '[{"day":"Day 1","title":"Hanoi Arrival – Half-Day City Tour","loc":"Hanoi, Vietnam","meals":"Lunch & Dinner Included (Indian Restaurant)","desc":"Welcome to Hanoi, Vietnam! Pick up at Noi Bai Airport and transfer to central Hanoi for hotel check-in (14:00). Enjoy an authentic Indian lunch followed by iconic cultural sightseeing.","schedule":["Airport pickup: Local tour guide and private driver meet you at Noi Bai Airport and transfer to Hanoi centre.","12:00 PM: Transfer to a reputable Indian restaurant for lunch.","Visit the Temple of Literature, Vietnam\'s first university constructed in 1070.","Stop at Ba Dinh Square and take photographs of Ho Chi Minh\'s Mausoleum from the outside.","Visit Hoan Kiem Lake and the sacred Ngoc Son Temple.","Take a classic cyclo tour around Hanoi\'s bustling Old Quarter.","Transfer to an Indian restaurant for dinner.","Return to the hotel. Overnight stay in Hanoi. (Note: Landing flight recommended around 12:00 PM or a little later)."],"image":"/assets/images/packages/vietnam.jpg"},{"day":"Day 2","title":"Full-Day Ninh Binh – Hoa Lu Ancient Capital, Bich Dong & Tam Coc","loc":"Ninh Binh Province (~100 km south of Hanoi)","meals":"Breakfast, Lunch & Dinner Included","desc":"Explore Ninh Binh Province. Discover the ancient 10th-century royal capital Hoa Lu, cave pagoda Bich Dong, and cruise on a sampan through the limestone grottos of Tam Coc.","schedule":["09:00 AM: Meet the guide at the hotel and transfer south to Ninh Binh Province.","Visit Hoa Lu, the former capital of Vietnam built in the 10th century by the Dinh Dynasty.","Visit the two ancient temples dedicated to King Dinh Tien Hoang and the succeeding kings of the Le Dynasty.","Visit Bich Dong Pagoda, an ancient three-tiered cave pagoda accessible by steep stone steps.","Enjoy lunch at an Indian restaurant.","Afternoon: Take a traditional sampan cruise along the Hoang Long River through Tam Coc\'s scenic landscape.","Explore limestone karst mountains, wetlands, and paddy fields, passing directly through three large caves.","05:00 PM: Transfer back to Hanoi.","Dinner at an Indian restaurant. Overnight stay in Hanoi."],"image":"/assets/images/tour/tour-details.jpg"},{"day":"Day 3","title":"Hanoi to Halong Bay – Overnight Luxury Cruise","loc":"Halong Bay & Bai Tu Long Bay","meals":"Breakfast, Lunch & Dinner on Board Included","desc":"Travel to Halong Bay, board your luxury cruise, savor Vietnamese set-menu lunch while sailing Bai Tu Long Bay, kayak at Cap La Island, and enjoy an evening sunset party.","schedule":["Breakfast at the hotel and check-out.","09:00 AM: Pick-up from the hotel and departure for Halong Bay, with a short rest stop en route.","12:30 PM: Arrive at the waiting lounge at Halong International Cruise Port.","12:45 PM: Welcome drink, safety briefing, and cabin check-in.","01:30 PM: Vietnamese set-menu lunch while cruising into Bai Tu Long Bay.","03:00 PM: Arrive at Cap La Island for kayaking, swimming, and relaxation.","05:30 PM: Return to the boat and enjoy the sunset party on the sundeck.","07:00 PM: Dinner on board.","08:30 PM: Free time for Vietnamese puzzle games, board games, squid fishing, or enjoying a cocktail. Overnight stay on cruise in Halong Bay."],"image":"/assets/images/destination/des1.jpg"},{"day":"Day 4","title":"Halong Cave Exploration – Flight to Danang","loc":"Halong Bay to Danang","meals":"Breakfast, Brunch & Dinner Included","desc":"Sunrise Tai Chi session, explore Thien Canh Son Cave, cooking demonstration on board, and private transfer to Noi Bai Airport for flight to Danang.","schedule":["06:00 AM: Sunrise Tai Chi session on the sundeck or enjoy morning bay views with tea or coffee.","07:00 AM: Western-style breakfast on board.","08:00 AM: Explore Thien Canh Son Cave.","09:00 AM: Return to boat, freshen up, and finish packing.","10:00 AM: Vietnamese cooking demonstration featuring Nem Cuon or fruit/vegetable carving.","11:00 AM: Traditional Vietnamese lunch on board.","12:00 PM: Disembark at Halong Cruise Port.","12:10 PM: Private transfer to Noi Bai Airport.","04:00 PM: Arrive at airport and check in for flight to Danang (recommended departure 06:00 PM or later).","Arrival in Danang, warm welcome by local guide, transfer to an Indian restaurant for dinner, followed by hotel check-in. Overnight stay in Danang."],"image":"/assets/images/destination/img1.jpg"},{"day":"Day 5","title":"Full-Day Ba Na Hills (Golden Bridge) & Hoi An Ancient Town","loc":"Ba Na Hills & Hoi An, Central Vietnam","meals":"Breakfast, Buffet Lunch & Dinner Included","desc":"Ascend 1,487m by cable car to Ba Na Hills and walk the Golden Bridge. In the afternoon, discover UNESCO-listed Hoi An Ancient Town and enjoy a magical lantern boat ride.","schedule":["09:00 AM: After breakfast, transfer to Ba Na Hills.","Take a cable car to the mountain summit at approximately 1,487 metres above sea level.","Visit Funicular, Le Jardin D\'Amour, Linh Ung Pagoda, and the Thich Ca Buddhist statue.","Buffet lunch with an Indian menu at a restaurant in Ba Na Hills.","Afternoon: Enjoy activities and games at Fantasy Park, Bell Tower, Nghinh Phong Tower, and walk the iconic Golden Bridge.","03:00 PM: Take the cable car back to foothill and transfer to Hoi An Town.","Walk across the 400-year-old Japanese Bridge, visit Chinese Assembly Halls, ancient merchant houses, shrines, and market beside Thu Bon River.","Shop for lanterns, silk, or tailored clothing.","Enjoy a lantern boat ride in Hoi An at night (approximately 15–20 minutes).","08:30 PM: Transfer to an Indian restaurant for dinner. Overnight stay in Danang."],"image":"/assets/images/destination/des5.jpg"},{"day":"Day 6","title":"Flight to Phu Quoc Island – Sunset Town & Kiss Bridge","loc":"Phu Quoc Island","meals":"Breakfast, Lunch & Dinner Included","desc":"Fly to tropical Phu Quoc Island. Savor an Indian lunch, explore Sunset Town, walk across the architectural Kiss Bridge, and watch the Symphony of the Sea show.","schedule":["Breakfast at the hotel and check-out.","Transfer to airport with local guide for flight to Phu Quoc.","Arrival, welcome by local guide, and hotel check-in (14:00).","12:00 PM: Transfer to an Indian restaurant for lunch.","05:00 PM: Transfer to south of island to visit Kiss Bridge and enjoy the Symphony of the Sea Show.","Dinner at Sun Bavaria restaurant.","10:00 PM: Transfer back to hotel. Overnight stay in Phu Quoc."],"image":"/assets/images/packages/andaman-beach.jpg"},{"day":"Day 7","title":"Full-Day Vinpearl Safari & VinWonders Theme Park","loc":"Phu Quoc","meals":"Breakfast, Buffet Lunch & Dinner Included","desc":"Explore Vietnam\'s premier open semi-wild conservation park at Vinpearl Safari, followed by world-class thrill rides and castle attractions at VinWonders.","schedule":["Breakfast at hotel.","09:00 AM: Transfer with local guide to discover Vinpearl Safari and VinWonders.","Explore Vietnam\'s largest open conservation wildlife park featuring hundreds of rare species in open habitats.","Buffet lunch at VinWonders.","Experience exciting rides, water kingdom, and adventure games at VinWonders.","Transfer to an Indian restaurant for dinner.","Return to hotel. Overnight stay in Phu Quoc."],"image":"/assets/images/explore/8.jpg"},{"day":"Day 8","title":"Full-Day 3 Islands Snorkelling & Aquatopia Water Park (SIC)","loc":"South Phu Quoc Islands","meals":"Breakfast, Boat Lunch & Dinner Included","desc":"Island boat tour to Gam Ghi coral reef and May Rut Trong white-sand beach. Explore Aquatopia Water Park and return via the spectacular sea cable car.","schedule":["07:30 AM: Pick-up from hotel lobby in central Duong Dong Town (Tran Hung Dao Street to Eden Resort).","Arrive at harbour and board tourist boat to visit three islands in the south.","Gam Ghi Island: Snorkelling at vibrant coral reef (mask, snorkel, and life jacket provided).","May Rut Trong Island: White-sand lagoon and beach, water sports, beach bar, and relaxation.","Enjoy freshly prepared lunch on board the boat.","Thom Island: Visit Aquatopia Water Park featuring 20+ modern rides and games.","Return by world-famous sea cable car (~25 minutes), enjoying panoramic sunset island views.","05:30 PM: Return to hotel.","07:00 PM: Transfer to an Indian restaurant for dinner. Overnight stay in Phu Quoc."],"image":"/assets/images/tour/2.jpg"},{"day":"Day 9","title":"Phu Quoc Departure – Cherished Memories","loc":"Phu Quoc Airport Departure","meals":"Breakfast Included","desc":"Breakfast at the hotel, check out by 12:00 PM, and transfer with your local guide to the airport for your departure flight.","schedule":["Breakfast at the hotel.","Check out (standard check-out time is 12:00 PM).","Transfer with the local guide to Phu Quoc Airport for departure flight.","Tour ends with golden memories of Vietnam."],"image":"/assets/images/travel-list/6.jpg"}]', '["Two nights hotel accommodation with breakfast in Hanoi.","One night on an overnight luxury cruise in Halong Bay.","Two nights hotel accommodation with breakfast in Danang.","Three nights hotel accommodation with breakfast in Phu Quoc.","All buffet breakfasts at hotels.","One lunch, one dinner, one breakfast, and one brunch on the Halong Bay cruise.","Three lunches and six dinners at Indian restaurants.","One buffet lunch with an Indian menu at Ba Na Hills.","One buffet lunch at VinWonders.","One set-menu dinner at Sun Bavaria restaurant.","Driver and private air-conditioned vehicle during all tours and transfers.","Experienced English-speaking guide during all tours and transfers.","Entrance fees for all visits mentioned in the itinerary.","Private boat trips at Tam Coc (Ninh Binh) and Hoi An lantern boat ride.","SIC 3-islands boat tour with snorkelling gear, cable car, and Aquatopia ticket.","Complimentary mineral water: two bottles per person per day."]', '["International and domestic airfares (Hanoi-Danang, Danang-Phu Quoc, and airport taxes).","Vietnam entry tourist visa.","Drinks and meals not clearly mentioned.","Surcharges for special food or meal requests.","Insurance, gratuities, and personal expenses.","Compulsory tips for guide and driver (US$ 5 per person per day for 4 pax).","Wax Museum and Debay Wine Cellar at Ba Na Hills (at guest\'s own expense).","Public holiday surcharges, if any."]', '["1. Standard check-in time is 14:00 and check-out is 12:00 PM.","2. Flight on Day 1 should arrive in Hanoi around 12:00 PM or a little later to match itinerary.","3. Flight on Day 4 should depart Hanoi for Danang at 06:00 PM or later.","4. Halong cruise itinerary may change depending on selected vessel and sea weather.","5. Day 8 island tour is subject to weather; cable car timing may be adjusted by guide.","6. Tips for guide and driver must be paid directly to the guide."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Vietnam Tour Package | Hanoi, Halong Bay Cruise, Da Nang & Phu Quoc | Golden Travels', 'Handcrafted 9-day Vietnam holiday: 5-star Halong Bay overnight cruise, Golden Bridge Ba Na Hills, lantern-lit Hoi An and tropical Phu Quoc island beaches.', 'vietnam tour package, halong bay cruise, da nang golden bridge, phu quoc holiday, vietnam package from coimbatore', 'http://localhost:3000/tour/vietnam-beauty-of-vietnam', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (7, 'taiwan-taipei-explorer', 'TAIWAN PROGRAM – Taipei, North Coast & Cultural Wonders', 'Taiwan Explorer', 'INTERNATIONAL', 'international', 'Taiwan (Taipei, New Taipei & Beitou)', 'Taipei, Yehliu, Shifen, Jiufen & Beitou', 'Taipei, New Taipei, Keelung, Beitou', '6 Days | 5 Nights', 5, 6, 'Scenic & Cultural', '/assets/images/packages/taiwan.jpg', '[{"src":"/assets/images/packages/taiwan.jpg","title":"Yehliu Geopark & Queen\'s Head Rock Formation"},{"src":"/assets/images/destination/des5.jpg","title":"Shifen Old Street Sky Lanterns on Railway Tracks"},{"src":"/assets/images/tour/1.jpg","title":"Jiufen Historic Lantern-Lit Hillside Alleys"},{"src":"/assets/images/destination/2.jpg","title":"Yangmingshan Volcanic National Park"},{"src":"/assets/images/destination/img1.jpg","title":"Maokong Tea Mountain Scenic Gondola"},{"src":"/assets/images/travel-list/6.jpg","title":"Beitou Geothermal Steaming Thermal Valley"}]', '["family","couple","friends","solo"]', '["5 Nights hotel accommodation as per selected category with daily breakfast","Tours and transfers as per itinerary with licensed English-speaking guide","Yehliu Geopark admission & Queen\'s Head rock formation","Shifen Old Street Sky Lantern release activity & Shifen Waterfall","Taiwan National Palace Museum admission & Beitou Thermal Valley","Maokong Gondola cable car ride & Tea Promotion Centre","Three lunches at NTD 600 per meal at quality local restaurants","Four dinners at NTD 800 per meal at quality local restaurants","Comprehensive Travel Insurance included"]', '["Taiwan","Taipei","Yehliu","Shifen","Jiufen","Yangmingshan","Maokong","Beitou","Ximending","Raohe","International","Asia"]', 'Discover the vibrant energy and scenic wonders of Taiwan on this 5 Nights / 6 Days journey through Taipei and its captivating north coast.\n\nFrom the extraordinary wind-carved geological sculptures at Yehliu Geopark to releasing traditional glowing sky lanterns along the railway tracks of Shifen, wandering the lantern-draped hillside lanes of Jiufen, soaking in the misty emerald vistas of Beitou Thermal Valley, and riding the Maokong Gondola over lush tea plantations, this tour combines Taiwan\'s rich heritage, volcanic landscapes, and legendary night market culinary scenes.', '[{"day":"Day 1","title":"Taoyuan Airport to Taipei Hotel – Transfer & Ximen Night Market","loc":"Taipei, Taiwan","meals":"Dinner Included (NTD 800/meal)","desc":"Arrival at Taoyuan International Airport, private transfer to Taipei hotel, visit Chiang Kai-shek Memorial Hall, and experience vibrant Ximen Night Market.","schedule":["Taoyuan Airport to Taipei Hotel transfer with local guide.","Taipei local transfer to Chiang Kai-shek Memorial Hall, honoring Taiwan\'s historical leader with grand liberty plaza.","Visit Ximen Night Market (Ximending), a vibrant youth district famous for street food, trendy boutiques, and nightlife.","Dinner at a local restaurant (NTD 800 per meal).","Overnight stay in Taipei."],"image":"/assets/images/packages/taiwan.jpg"},{"day":"Day 2","title":"Taipei – North Coast Sightseeing (Yehliu, Shifen & Jiufen)","loc":"New Taipei Coast & Mountains","meals":"Breakfast, Lunch & Dinner Included","desc":"Explore Yehliu Geopark\'s Queen\'s Head rock formations, release sky lanterns at Shifen Old Street, visit Shifen Waterfall, and stroll through Jiufen Old Street.","schedule":["Breakfast at hotel. Taipei local transfer to the north coast.","Yehliu Geopark: Explore a unique coastal landscape famous for rock formations such as the Queen\'s Head, shaped by wind and sea erosion.","Shifen Old Street: Historic railway town known for sky lantern releases, local snacks, and shops along the active train tracks.","Visit Shifen Waterfall, Taiwan\'s broad horseshoe waterfall.","Lunch at local restaurant (NTD 600 per meal).","Jiufen Old Street: Atmospheric former gold mining village perched on mountain slopes with glowing lanterns and teahouses.","Dinner at local restaurant (NTD 800 per meal).","Overnight stay in Taipei."],"image":"/assets/images/destination/des5.jpg"},{"day":"Day 3","title":"Taipei – Nature, Culture & Raohe Night Market","loc":"Yangmingshan, Beitou & Taipei","meals":"Breakfast, Lunch & Dinner Included","desc":"Experience the volcanic beauty of Yangmingshan National Park, imperial treasures at the National Palace Museum, Beitou Thermal Valley, and Raohe Night Market.","schedule":["Breakfast at hotel. Taipei local transfer.","Yangmingshan National Park: Known for volcanic landscapes, hot spring steam vents, flower fields, and mountain views.","Taiwan National Palace Museum: Explore ancient Chinese art and artefacts, including jade carvings, calligraphy, paintings, and ceramics.","Lunch at local restaurant (NTD 600 per meal).","Beitou Thermal Valley: Explore the emerald-green geothermal lake and natural hot spring source.","Raohe Night Market: One of Taipei\'s oldest night markets, celebrated for Michelin-recommended pepper buns and street delicacies.","Dinner at local restaurant (NTD 800 per meal).","Overnight stay in Taipei."],"image":"/assets/images/tour/1.jpg"},{"day":"Day 4","title":"Taipei – Maokong Gondola, Tea Culture & Zhinan Temple","loc":"Muzha & Taipei 101 District","meals":"Breakfast, Lunch & Dinner Included","desc":"Scenic Maokong Gondola cable car ride, Tea Promotion Centre, Taoist Zhinan Temple, and Taipei 101 district sightseeing.","schedule":["Breakfast at hotel. Taipei local transfer.","Visit Maokong Gondola: Ride the scenic cable car gliding above lush mountain forests and tea plantations.","Visit Tea Promotion Centre: Learn about Taiwan\'s tea culture, harvesting, brewing, and locally grown Oolong tea.","Visit Zhinan Temple, a historic Taoist complex with panoramic city views.","Lunch at local restaurant (NTD 600 per meal).","Taipei 101 district sightseeing (Taipei 101 indoor observatory admission excluded).","Dinner at local restaurant (NTD 800 per meal).","Overnight stay in Taipei."],"image":"/assets/images/destination/img1.jpg"},{"day":"Day 5","title":"Taipei to Gloria Outlet Shopping Extravaganza","loc":"Taoyuan & Taipei","meals":"Breakfast & Dinner Included","desc":"Visit Gloria Outlet, Taiwan\'s largest American-style outdoor outlet mall near Taoyuan, featuring international brands and discount shopping.","schedule":["Breakfast at hotel.","Transfer to Gloria Outlet: Taiwan\'s premier American-style open-air outlet mall featuring international brands, dining, and discount shopping.","Free leisure time for shopping, souvenirs, and cafe relaxation.","Farewell dinner at local restaurant (NTD 800 per meal).","Overnight stay in Taipei."],"image":"/assets/images/travel-list/6.jpg"},{"day":"Day 6","title":"Taipei Hotel to Taoyuan International Airport – Departure","loc":"Taoyuan Airport Departure","meals":"Breakfast Included","desc":"Breakfast at hotel, checkout, and private transfer to Taoyuan International Airport for your departure flight.","schedule":["Breakfast at hotel and check-out.","Transfer from Taipei hotel to Taoyuan International Airport with local tour guide.","Departure assistance for flight check-in.","Tour ends with golden memories of Taiwan."],"image":"/assets/images/destination/2.jpg"}]', '["Accommodation as per selected hotel category with daily breakfast.","Tours and transfers as per itinerary with licensed local tour guide.","Admission included for Yehliu Geopark, Shifen Lantern activity, National Palace Museum, and Maokong Gondola.","One bottle of water per person per day.","Three lunches at NTD 600 per meal at local restaurants.","Four dinners at NTD 800 per meal at local restaurants.","Comprehensive Travel Insurance included."]', '["International round-trip airfare.","Taipei 101 Observatory admission is excluded.","USD 5 per person per day for the tour guide and coach driver is excluded.","Other personal expenses (laundry, telephone, alcoholic drinks).","Any unused portion of the package is non-refundable.","If a passenger cannot pass immigration at the international airport, the tour fare is non-refundable."]', '["1. Standard hotel check-in time is 15:00 and check-out is 11:00 AM.","2. Passport must have minimum 6 months validity.","3. Tipping of USD 5 per person per day payable directly to guide/driver.","4. Anything not mentioned in the inclusions is excluded."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Taiwan Tour Package | Taipei, Yehliu Geopark & Jiufen Old Street | Golden Travels', 'Experience Taiwan blend of modern tech and ancient heritage: Taipei 101, Shifen sky lanterns, Jiufen mountain tea houses & Yehliu rock formations.', 'taiwan tour package, taipei 101 trip, jiufen shifen tour, yehliu geopark, taiwan holiday package', 'https://goldentravels.in/tour/taiwan-taipei-explorer', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (8, 'spain-barcelona-madrid', 'SPAIN PROGRAM – Barcelona & Madrid Grand Discovery', 'Spain Highlights', 'INTERNATIONAL', 'international', 'Spain (Catalonia & Madrid)', 'Barcelona & Madrid, Spain', 'Barcelona, Madrid', '7 Days | 6 Nights', 6, 7, 'European Heritage', '/assets/images/packages/spain.jpg', '[{"src":"/assets/images/packages/spain.jpg","title":"Sagrada Familia Basilica & Antoni Gaudí Masterpiece"},{"src":"/assets/images/tour/tour-details.jpg","title":"Historic Gothic Quarter & Cathedral of Barcelona"},{"src":"/assets/images/tour/2.jpg","title":"Plaza Mayor & Puerta del Sol, Madrid"},{"src":"/assets/images/tour/3.jpg","title":"Montjuïc Panoramic Cable Car Barcelona"},{"src":"/assets/images/destination/des2.jpg","title":"Puerta de Alcalá & Plaza de Cibeles, Madrid"},{"src":"/assets/images/page/explore3.jpg","title":"Santiago Bernabéu Stadium & Gran Vía Avenue"}]', '["family","couple","friends","solo"]', '["Six nights hotel accommodation in Barcelona and Madrid","Daily buffet breakfast at hotels","All transfers and tours on private basis","Round-trip high-speed train tickets: Barcelona – Madrid – Barcelona (second class)","Walking tour of Born neighbourhood & Gothic Quarter","Entry to Cathedral of Barcelona & Montjuïc Cable Car ride","Full-day Barcelona Highlights tour & Sagrada Familia guided visit","Madrid Panoramic Bus Tour (Plaza Mayor, Puerta de Alcalá, Cibeles, Bernabéu)"]', '["Spain","Barcelona","Madrid","Sagrada Familia","Gaudí","Gothic Quarter","Plaza Mayor","Bernabeu","Europe","International"]', 'Immerse yourself in the passion, art, and grand imperial architecture of Spain on this classic 6 Nights / 7 Days journey connecting Barcelona and Madrid.\n\nMarvel at Antoni Gaudí\'s awe-inspiring masterpiece, the Sagrada Familia, wander through medieval stone alleyways in Barcelona\'s Gothic Quarter, and soak in Mediterranean vistas from the Montjuïc Cable Car. Whisk across the Iberian peninsula aboard a high-speed train to Madrid, Spain\'s regal capital, where grand plazas like Plaza Mayor and Puerta del Sol, iconic monuments, and football royalty at Santiago Bernabéu Stadium await.', '[{"day":"Day 1","title":"Barcelona Arrival – Welcome to Spain","loc":"Barcelona, Spain","meals":"Breakfast (Subsequent Days)","desc":"Arrive in Barcelona and transfer to your hotel. The rest of the day is free for leisure exploring Las Ramblas or the Mediterranean beachfront.","schedule":["Arrive at Barcelona Airport (BCN).","Meet your driver and transfer comfortably to your hotel.","Check in and relax.","The rest of the day is free for leisure: stroll down Las Ramblas, Plaça de Catalunya, or enjoy authentic tapas.","Overnight stay: Barcelona."],"image":"/assets/images/packages/spain.jpg"},{"day":"Day 2","title":"Barcelona – City Discovery, Gothic Quarter & Cable Car","loc":"Barcelona City Discovery","meals":"Daily Breakfast Included","desc":"Discover Barcelona and its history with a walking tour of the Born neighbourhood, Gothic Quarter, Cathedral of Barcelona, panoramic coach tour, and cable car views.","schedule":["In the morning, discover Barcelona and its rich history.","Walking tour of the vibrant Born neighbourhood.","Explore the historic Gothic Quarter with its Roman and medieval alleys.","Enter the majestic Cathedral of Barcelona.","Board an air-conditioned coach for a panoramic city tour.","Enjoy breathtaking city views from the Montjuïc cable car.","Overnight stay: Barcelona."],"image":"/assets/images/tour/tour-details.jpg"},{"day":"Day 3","title":"Barcelona – Highlights and Sagrada Familia","loc":"Barcelona Landmarks","meals":"Daily Breakfast Included","desc":"Proceed for a full-day Barcelona Highlights tour with a panoramic bus ride covering iconic sights and an afternoon visit to Gaudí\'s Sagrada Familia.","schedule":["In the morning, proceed for a full-day Barcelona Highlights tour.","Panoramic bus tour covering Barcelona\'s iconic modernist sights and grand avenues.","Afternoon visit to the world-renowned Basilica de la Sagrada Familia.","Admire the architectural genius of Antoni Gaudí and the profound symbolism of the basilica façades and interior columns.","Overnight stay: Barcelona."],"image":"/assets/images/destination/des2.jpg"},{"day":"Day 4","title":"Barcelona to Madrid by High-Speed Train","loc":"Barcelona to Madrid, Spain","meals":"Daily Breakfast Included","desc":"Board the high-speed train from Barcelona to Madrid. Transfer to hotel upon arrival with the rest of the day free for leisure.","schedule":["Breakfast at hotel and check-out.","Proceed to Barcelona train station and board the high-speed train to Madrid.","Upon arrival in Madrid, transfer to your hotel.","The rest of the day is free for leisure: discover Gran Vía, Puerta del Sol, or Retiro Park.","Overnight stay: Madrid."],"image":"/assets/images/tour/2.jpg"},{"day":"Day 5","title":"Madrid – Panoramic City Sightseeing","loc":"Madrid Imperial Capital","meals":"Daily Breakfast Included","desc":"Proceed for a panoramic bus tour of Madrid covering Plaza Mayor, Puerta de Alcalá, Plaza de Cibeles, Puerta del Sol, and Bernabéu Stadium.","schedule":["Breakfast at hotel.","Proceed for a panoramic bus tour of Madrid.","Places covered include: Plaza Mayor, Puerta de Alcalá, Plaza de Cibeles, Puerta del Sol, and Santiago Bernabéu Stadium.","Stop at selected landmark locations to take photographs.","Overnight stay: Madrid."],"image":"/assets/images/tour/3.jpg"},{"day":"Day 6","title":"Madrid to Barcelona by High-Speed Train","loc":"Madrid to Barcelona","meals":"Daily Breakfast Included","desc":"Board the high-speed train back to Barcelona. Transfer to hotel with free leisure time for last-minute shopping and dining.","schedule":["Breakfast at hotel and check-out.","Proceed to Madrid train station and board the return train to Barcelona.","Upon arrival in Barcelona, transfer to the hotel.","The rest of the day is free for leisure: enjoy shopping or seaside relaxation at Port Vell.","Overnight stay: Barcelona."],"image":"/assets/images/page/explore3.jpg"},{"day":"Day 7","title":"Barcelona – Departure","loc":"Barcelona Airport Departure","meals":"Daily Breakfast Included","desc":"Breakfast at hotel and depart for Barcelona Airport on your own for your flight to your final destination.","schedule":["Breakfast at hotel and check-out.","Depart for Barcelona Airport on your own for your flight to your final destination.","Tour ends with golden memories of Spain. (Note: Airport transfer on departure day is not included in the itinerary)."],"image":"/assets/images/explore/7.jpg"}]', '["Six nights hotel accommodation (Barcelona & Madrid).","Daily breakfast at hotels.","All transfers and tours on a private basis.","Round-trip train tickets: Barcelona – Madrid – Barcelona, second class.","Sightseeing tours as mentioned in itinerary.","Born & Gothic Quarter walking tour + Cathedral of Barcelona entry.","Barcelona panoramic coach tour and Montjuïc cable car ticket.","Sagrada Familia admission and architectural tour.","Madrid Panoramic Bus Tour (Plaza Mayor, Cibeles, Bernabéu Stadium)."]', '["International round-trip airfare.","Airport transfer on the departure day is not included.","Schengen visa fees.","Lunches and dinners.","Other personal expenses (laundry, telephone, tips, beverages).","Travel and medical insurance."]', '["1. Standard hotel check-in time is 15:00 and check-out is 11:00 AM.","2. Round-trip train tickets are 2nd class as per availability.","3. Sagrada Familia entry timings are subject to strict basilica schedule.","4. Anything not mentioned in the inclusions is excluded."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Spain Tour Package | Barcelona, Madrid & High-Speed Train Journey | Golden Travels', 'Discover Spain architectural icons: Sagrada Familia, Park Guell, Royal Palace of Madrid and high-speed AVE train transfers with visa assistance.', 'spain tour package, barcelona madrid trip, sagrada familia tour, spain holiday package, europe tours from coimbatore', 'https://goldentravels.in/tour/spain-barcelona-madrid', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (9, 'south-korea-seoul-busan', 'SOUTH KOREA PROGRAM – Seoul Royal Palaces & Coastal Busan', 'South Korea Explorer', 'INTERNATIONAL', 'international', 'South Korea (Seoul & Busan)', 'Seoul, N Seoul Tower, Lotte World & Busan', 'Seoul, Busan', '5 Days | 4 Nights', 4, 5, 'K-Culture & Coastal', '/assets/images/packages/south-korea.jpg', '[{"src":"/assets/images/packages/south-korea.jpg","title":"Gyeongbokgung Palace & Hanok Heritage"},{"src":"/assets/images/destination/1.jpg","title":"N Seoul Tower & Namsan Mountain Cable Car"},{"src":"/assets/images/destination/des1.jpg","title":"Gamcheon Culture Village Colorful Houses, Busan"},{"src":"/assets/images/travel-list/1.jpg","title":"Songdo Air Capsule & Haeundae Beach Train"},{"src":"/assets/images/travel-list/4.jpg","title":"Lotte World Tower & Suyeong Bay Yacht Tour"}]', '["family","couple","friends","solo"]', '["Accommodation as per the table mentioned in selected Seoul & Busan hotels","Tours and transfers as per itinerary with a basic English-speaking driver","Round-trip KTX high-speed train tickets: Seoul – Busan – Seoul","Gyeongbok Palace & Royal Changing of the Guard ceremony","National Folk Museum & Bukchon Hanok Village tour","N Seoul Tower observatory & round-trip cable car","Lotte Tower & Lotte World theme park admission","Songdo Air Capsule & Haeundae Blue Line Park one-way beach train","Suyeong Bay luxury yacht tour in Busan"]', '["South Korea","Seoul","Busan","Gyeongbokgung","N Seoul Tower","Lotte World","Haeundae","Gamcheon","KTX Train","International","Asia"]', 'Experience the captivating blend of ultra-modern spectacle and ancient Joseon dynasty heritage on this 4 Nights / 5 Days South Korea adventure spanning Seoul and Busan.\n\nWitness the royal Changing of the Guard at Gyeongbokgung Palace, stroll through the picturesque alleys of Bukchon Hanok Village, ascend N Seoul Tower, and experience thrills at Lotte World. Then ride the high-speed KTX bullet train to Busan, South Korea\'s vibrant coastal metropolis, to explore the colorful hillside houses of Gamcheon Culture Village, ride the retro Songdo Air Capsule and Haeundae Beach Train, and sail on a luxury sunset yacht cruise in Suyeong Bay.', '[{"day":"Day 1","title":"Incheon Airport to Seoul Hotel – Airport Transfer","loc":"Seoul, South Korea","meals":"Breakfast (Subsequent Days)","desc":"Airport transfer from Incheon Airport to the Seoul hotel (driver only). Check in and enjoy the evening at leisure in Seoul.","schedule":["Incheon Airport to Seoul Hotel – Airport transfer with driver only.","Arrival at Seoul hotel and check-in.","Free leisure evening: explore Myeongdong shopping street or nearby Korean BBQ dining.","Overnight stay: Seoul."],"image":"/assets/images/packages/south-korea.jpg"},{"day":"Day 2","title":"Seoul – City Sightseeing, Palaces & N Seoul Tower","loc":"Seoul Historic Centre","meals":"Breakfast Included","desc":"Local sightseeing in Seoul with driver only: Gyeongbok Palace guard change, National Folk Museum, Bukchon Hanok Village, Insadong, and N Seoul Tower cable car.","schedule":["Local sightseeing in Seoul with a driver only.","Gyeongbok Palace: Visit the palace and witness the changing of the guard ceremony.","National Folk Museum: Explore Korean folk culture and traditions.","Bukchon Hanok Village: Tour the traditional Korean village with preserved wooden hanoks.","Insadong Culture Street: Explore the cultural street famous for crafts and tea houses.","N Seoul Tower: Visit the observatory and enjoy the round-trip cable car.","Overnight stay: Seoul."],"image":"/assets/images/destination/1.jpg"},{"day":"Day 3","title":"Seoul – Lotte Tower & Lotte World Theme Park","loc":"Jamsil, Seoul","meals":"Breakfast Included","desc":"Local transfer in Seoul with a driver only to visit Lotte Tower, South Korea\'s tallest skyscraper, and enjoy world-class rides at Lotte World.","schedule":["Local transfer in Seoul with a driver only.","Visit Lotte Tower: Ascend to the glass observatory for panoramic skyline views across Seoul.","Visit Lotte World: Experience thrilling rides, indoor adventure zones, and outdoor Magic Island.","Return transfer to hotel with driver only.","Overnight stay: Seoul."],"image":"/assets/images/travel-list/4.jpg"},{"day":"Day 4","title":"Seoul to Busan by KTX Train – Coastal City Tour","loc":"Seoul to Busan","meals":"Breakfast Included","desc":"Transfer to Seoul Station, high-speed KTX train to Busan, and coastal city tour covering Gamcheon Culture Village, Songdo Air Capsule, and Haeundae Beach Train.","schedule":["Transfer from Seoul hotel to Seoul Station with a driver only.","Travel from Seoul to Busan by KTX train.","Transfer from Busan Station for the city tour with a driver only.","Visit Gamcheon Culture Village, known for vibrant pastel houses and hillside art.","Experience Songdo Air Capsule scenic coastal ride.","Enjoy Haeundae Blue Line Park with a one-way beach train.","Visit Haeundae Beach for coastal relaxation.","Overnight stay: Busan."],"image":"/assets/images/destination/des1.jpg"},{"day":"Day 5","title":"Busan – Sightseeing, Yacht Tour & Departure via Seoul","loc":"Busan to Seoul Airport","meals":"Breakfast Included","desc":"Local sightseeing in Busan with driver only: Suyeong Bay Yacht Tour, Gwangalli Beach, Haedong Yonggungsa Temple, KTX to Seoul, and airport transfer.","schedule":["Local sightseeing in Busan with a driver only.","Suyeong Bay Yacht Tour enjoying Busan\'s marine skyline.","Visit Gwangalli Beach with views of Diamond Bridge.","Visit Haedong Yonggungsa Temple, a spectacular Buddhist temple built on ocean cliffs.","Transfer from Busan to Busan Station.","Travel from Busan to Seoul by KTX train.","Transfer from Seoul Station to Seoul Airport for departure.","Tour ends with golden memories of South Korea."],"image":"/assets/images/tour/6.jpg"}]', '["Accommodation as per the table mentioned in selected hotels.","Tours and transfers as per the itinerary with a basic English-speaking driver.","Admission fees for attractions mentioned in the itinerary (Gyeongbok Palace, N Seoul Tower & cable car, Lotte Tower, Lotte World, Songdo Air Capsule, Haeundae Beach Train, Yacht Tour).","One bottle of water per person per day.","Round-trip KTX train tickets: Seoul – Busan – Seoul."]', '["International round-trip airfare.","Lunch and dinner.","USD 5 per person per day for the tour guide and coach driver is excluded.","Other personal expenses.","Any unused portion of the package is non-refundable.","If a passenger cannot pass immigration at the international airport, the tour fare is non-refundable."]', '["1. Standard check-in time is 15:00 and check-out is 11:00 AM.","2. Drivers are basic English-speaking chauffeurs.","3. KTX ticket seats are subject to availability at booking time.","4. Anything not mentioned in the inclusions is excluded."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'South Korea Tour Package | Seoul Royal Palaces, Lotte World & Coastal Busan | Golden Travels', 'Immerse in K-culture, Gyeongbokgung royal palace, KTX bullet train to Busan beaches and Gamcheon Culture Village with expert-guided tours.', 'south korea tour package, seoul busan trip, lotte world seoul, korea holiday package, k-drama tour', 'https://goldentravels.in/tour/south-korea-seoul-busan', 1, 1);
INSERT INTO `packages` (`id`, `slug`, `title`, `shortTitle`, `type`, `category`, `region`, `destination`, `cities`, `duration`, `nights`, `days`, `badge`, `image`, `gallery`, `personas`, `keyInclusions`, `tags`, `about`, `itinerary`, `inclusions`, `exclusions`, `terms`, `isActive`, `featured`, `createdAt`, `updatedAt`, `metaTitle`, `metaDescription`, `metaKeywords`, `canonicalUrl`, `showInExplore`, `showInExclusive`) VALUES (10, 'philippines-manila-angeles-pagsanjan', 'PHILIPPINES PROGRAM – Manila, Puning Hot Springs, Taal Volcano & Pagsanjan Falls', 'Philippines Tropical Adventure', 'INTERNATIONAL', 'international', 'Philippines (Manila, Angeles, Tagaytay, Laguna)', 'Manila, Angeles, Subic Bay, Tagaytay & Pagsanjan', 'Manila, Angeles, Subic Bay, Tagaytay, Pagsanjan', '6 Days | 5 Nights', 5, 6, 'Adventure & Island Gala', '/assets/images/packages/philippines.jpg', '[{"src":"/assets/images/packages/philippines.jpg","title":"Pagsanjan Falls Traditional Canoe River Rapids"},{"src":"/assets/images/destination/3.jpg","title":"Puning Hot Springs & Mt. Pinatubo 4x4 Lahar Trail"},{"src":"/assets/images/destination/des1.jpg","title":"Subic Bay Sunset Harbour Cruise"},{"src":"/assets/images/tour/tour-details2.jpg","title":"Intramuros Spanish Walled City & Fort Santiago"},{"src":"/assets/images/travel-list/5.jpg","title":"Taal Volcano Panoramic View Deck & Tagaytay"},{"src":"/assets/images/slide/slide1.jpg","title":"Exclusive Gala Dinner with 2-Hour DJ & Cultural Show"}]', '["family","couple","friends","solo"]', '["Five nights accommodation on twin/double-sharing basis (Angeles & Manila)","Daily breakfast at hotels","All lunches and dinners at Indian restaurants on an APAI basis + one local Filipino meal","Private deluxe air-conditioned coaches throughout the tour","English-speaking licensed tour guides throughout","Puning Hot Springs with 4x4 Mt. Pinatubo lahar ride, volcanic sand spa & mud therapy","Subic Bay Dinner Cruise with harbor views","Manila Heritage Tour (Intramuros, Fort Santiago, San Agustin Church)","Tagaytay & Taal Volcano tour + Crosswinds Swiss Village","Pagsanjan Falls excursion with traditional canoe ride","Exclusive Gala Dinner with soft drinks, veg/non-veg snacks, 2-hour DJ & cultural dance show","Travel insurance, guide/driver tips, GST, and TCS all included"]', '["Philippines","Manila","Angeles","Puning Hot Springs","Subic Bay","Tagaytay","Taal Volcano","Pagsanjan Falls","Intramuros","International","Asia"]', 'Embark on an exhilarating 5 Nights / 6 Days adventure across the Philippine archipelago\'s main island of Luzon, exploring thrilling volcanic landscapes, historic colonial fortresses, and roaring rainforest waterfalls.\n\nRide a 4x4 off-road vehicle across Mount Pinatubo\'s lahar canyons to rejuvenate in the natural thermal waters and volcanic sand spa of Puning Hot Springs. Cruise across Subic Bay at sunset, walk along the Spanish colonial cobblestones of Intramuros in Manila, admire panoramic views of Taal Volcano inside a lake, shoot the rapids on a traditional wooden canoe to Pagsanjan Falls, and celebrate with an Exclusive Gala Dinner complete with live DJ and cultural performances.', '[{"day":"Day 1","title":"Arrival Manila – Transfer to Angeles City","loc":"Manila to Angeles City (~2 hrs / 98 km)","meals":"Indian Dinner Included","desc":"Arrival at Ninoy Aquino International Airport, meet and greet, private deluxe coach transfer to Angeles City, hotel check-in, and authentic Indian dinner.","schedule":["Arrival at Ninoy Aquino International Airport (MNL).","Meet and greet by the Islas Pinas representative with baggage assistance and group assembly.","Bottled water provided.","Board private deluxe air-conditioned coaches and transfer to Angeles City (~2 hours / 98 km one way), with en-route sightseeing if time permits.","Hotel check-in in Angeles City.","Indian dinner at a designated Indian restaurant.","Overnight stay: Angeles."],"image":"/assets/images/packages/philippines.jpg"},{"day":"Day 2","title":"Puning Hot Springs & Subic Bay Dinner Cruise","loc":"Angeles & Subic Bay","meals":"Breakfast, Lunch & Cruise Dinner Included","desc":"Experience Puning Hot Springs with a 4x4 ride through Mt. Pinatubo lahar trails, natural thermal pools, volcanic sand spa, and evening Subic Bay Dinner Cruise.","schedule":["Breakfast at the hotel.","Proceed to Puning Hot Springs (travel duration ~30 minutes).","Enjoy a 4x4 adventure ride through Mount Pinatubo lahar trails.","Experience natural hot spring pools, volcanic sand spa experience, mud pack therapy, and therapeutic relaxation pools.","Lunch during the excursion.","Proceed to Subic Bay (travel duration ~1 hour 30 minutes one way).","Evening Subic Bay Dinner Cruise with dinner served onboard while enjoying scenic harbour and bay views.","Return to Angeles. Overnight stay: Angeles."],"image":"/assets/images/destination/3.jpg"},{"day":"Day 3","title":"Angeles to Manila – Heritage City Tour & Manila Bay Sunset","loc":"Historic Manila","meals":"Breakfast, Indian Lunch & Indian Dinner Included","desc":"Check out and transfer to Manila (~1.5 hrs). Visit Rizal Park, Intramuros, Fort Santiago, San Agustin Church, Mall of Asia, and Manila Bay sunset.","schedule":["Breakfast at the hotel, check out, and transfer to Manila (~1 hour 30 minutes one way).","Visit Rizal Park.","Explore walled city Intramuros: visit Fort Santiago, San Agustin Church, Casa Manila, and Manila Cathedral.","Indian lunch at a premier restaurant.","Enjoy the Mall of Asia shopping experience.","View the golden sunset at Manila Bay.","Indian dinner at designated restaurant.","Hotel check-in. Overnight stay: Manila."],"image":"/assets/images/tour/tour-details2.jpg"},{"day":"Day 4","title":"Taal Volcano & Tagaytay Highlights","loc":"Tagaytay & Batangas (~2 hrs one way)","meals":"Breakfast, Indian Lunch & Indian Dinner Included","desc":"Proceed to Tagaytay ridge. Visit People\'s Park in the Sky, Picnic Grove, Taal Volcano View Deck, Twin Lakes, and Crosswinds Swiss Village.","schedule":["Breakfast at the hotel.","Proceed to Tagaytay (travel duration ~2 hours one way).","Visit People\'s Park in the Sky.","Visit Picnic Grove and Taal Volcano View Deck to admire the scenic caldera lake.","Visit Twin Lakes and Crosswinds Swiss Village.","Scenic ridge photo stops and souvenir shopping opportunities.","Indian lunch.","Free leisure time.","Return to Manila.","Indian dinner. Overnight stay: Manila."],"image":"/assets/images/travel-list/5.jpg"},{"day":"Day 5","title":"Pagsanjan Falls Canoe Rapids & Exclusive Gala Dinner","loc":"Laguna & Manila","meals":"Breakfast, Packed Lunch & Gala Dinner Included","desc":"Travel to Pagsanjan (~3 hrs), take a traditional canoe ride to Pagsanjan Falls, followed by return to Manila for an Exclusive Gala Dinner with live DJ and dance show.","schedule":["Breakfast at the hotel.","Proceed to Pagsanjan (travel duration ~3 hours one way).","Enjoy a traditional wooden canoe ride shooting the rapids.","Visit Pagsanjan Falls and experience a scenic river gorge adventure.","Packed lunch provided.","Return to Manila.","Exclusive Gala Dinner: soft drinks, soda, ice and water, two vegetarian snacks, two non-vegetarian snacks, 2-hour DJ, and traditional cultural dance performance.","Overnight stay: Manila."],"image":"/assets/images/destination/des1.jpg"},{"day":"Day 6","title":"Manila Departure","loc":"Manila Airport Departure","meals":"Breakfast & Packed Travel Snack Included","desc":"Breakfast at the hotel, check out with packed travel snacks (sandwich, water, juice, fruit), and transfer by private coach to the airport.","schedule":["Breakfast at the hotel.","Check out with packed snacks, including a sandwich, water bottle, juice, and fruits.","Transfer to the airport by private coach.","Departure assistance for return flight.","Tour ends with golden memories of the Philippines."],"image":"/assets/images/slide/slide1.jpg"}]', '["Five nights accommodation on a twin/double-sharing basis.","Daily breakfast at hotels.","All lunches and dinners at Indian restaurants on an APAI basis.","One local Filipino meal.","Private deluxe air-conditioned coaches throughout the tour.","English-speaking tour guides.","Puning Hot Springs, including 4x4 ride and entrance fees.","Subic Bay Dinner Cruise.","Manila Heritage Tour (Intramuros, Fort Santiago, San Agustin Church).","Mall of Asia shopping experience & Manila Bay sunset view.","Tagaytay and Taal Volcano tour.","Pagsanjan Falls excursion with traditional canoe ride.","All entrance fees and sightseeing mentioned in the itinerary.","Guide and driver tips.","Water bottles during tours and transfers.","All applicable taxes (GST and TCS, as applicable).","Exclusive gala dinner with beverage package, snacks, 2-hour DJ, and cultural performance.","Travel insurance for all passengers."]', '["Airfare (international and domestic).","Porter service.","Hard drinks.","Hotel charges for additional services and penalties.","Charges for additional persons joining the group at destination.","Early check-in at hotels.","Any service not explicitly mentioned in the inclusions."]', '["1. Standard check-in time is 14:00 and check-out is 12:00 PM.","2. Puning Hot Springs and Pagsanjan canoe require basic agility.","3. Passports must have at least 6 months validity from date of departure.","4. Tour sequence may adjust based on local road traffic or weather conditions."]', 1, 1, '2026-10-12 06:43:03', '2026-10-22 06:08:51', 'Philippines Tour Package | Manila, Puning Hot Springs & Pagsanjan Falls | Golden Travels', 'Explore Manila historic Intramuros, shoot the rapids at Pagsanjan Falls, relax in Puning volcanic hot springs and marvel at Taal Volcano crater lake.', 'philippines tour package, manila pagsanjan falls, puning hot springs, taal volcano tour, philippines holiday', 'http://localhost:3000/tour/undefined', 1, 1);

