INSERT INTO `testimonials` (`id`, `name`, `role`, `text`, `rating`, `avatar`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (1, 'Priya & Rajesh Sharma', 'Honeymoon in Switzerland & Paris', '“Our Switzerland & Paris honeymoon planned by Golden Travels was an absolute fairytale! From panoramic Glacier Express tickets to romantic chalet bookings, everything was flawlessly organized with 24/7 WhatsApp concierge.”', 5, NULL, 1, 1, '2026-10-12 07:31:39', '2026-10-12 07:31:39');
INSERT INTO `testimonials` (`id`, `name`, `role`, `text`, `rating`, `avatar`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (2, 'Dr. Anand Ramanathan', 'Family Trip to Singapore & Bali', '“Traveling with children and senior parents can be stressful, but Golden Travels made it 100% effortless. Indian meals, private transfers, and handpicked luxury resorts made our vacation memorable and relaxing.”', 5, NULL, 2, 1, '2026-10-12 07:31:39', '2026-10-12 07:31:39');
INSERT INTO `testimonials` (`id`, `name`, `role`, `text`, `rating`, `avatar`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (3, 'Vikram Mehta & Family', 'Vietnam & Halong Bay Explorer', '“Booked a 9-day Vietnam package with Golden Travels. The Halong Bay luxury cruise, Ba Na Hills Golden Bridge, and Phu Quoc islands were magical. Authentic Indian meals and dedicated guides made our trip totally seamless!”', 5, NULL, 3, 1, '2026-10-12 07:31:39', '2026-10-12 07:31:39');

